window.QUESTIONS=[{"id":"java-01","topic":"Java","level":"하","question":"객체지향 프로그래밍의 4가지 특징을 자바 예시와 함께 설명해 보세요.","answer":"캡슐화는 필드를 private으로 숨기고 메서드로만 접근하게 해 상태를 보호하는 것입니다. 상속은 부모 클래스의 필드·메서드를 자식이 재사용·확장하는 것이고, 다형성은 같은 타입 참조로 서로 다른 구현을 호출하는 것입니다(부모 타입 변수에 자식 객체 대입). 추상화는 인터페이스·추상 클래스로 공통 동작만 드러내고 구체 구현은 감추는 것입니다.","keywords":["캡슐화","상속","다형성","추상화"],"source":"https://docs.oracle.com/javase/tutorial/java/concepts/index.html","followups":["그중 다형성이 실제 코드에서 어떻게 유지보수를 쉽게 해 주는지 예를 들어 보시겠어요?","상속 대신 합성(composition)을 권장하는 경우는 언제인가요?"]},{"id":"java-02","topic":"Java","level":"하","question":"메서드 오버로딩과 오버라이딩의 차이는 무엇인가요?","answer":"오버로딩은 같은 클래스에서 이름은 같고 매개변수의 타입·개수·순서가 다른 메서드를 여러 개 정의하는 것으로 컴파일 시점에 결정됩니다. 오버라이딩은 상속 관계에서 자식이 부모의 메서드를 같은 시그니처로 재정의하는 것이며 실제 객체 타입에 따라 실행 시점에 호출됩니다. 반환 타입만 다른 오버로딩은 불가능하고, @Override 애노테이션을 쓰면 시그니처 실수를 컴파일러가 잡아 줍니다.","keywords":["시그니처","컴파일 시점","런타임","@Override"],"source":"https://docs.oracle.com/javase/tutorial/java/IandI/override.html","followups":["static 메서드나 private 메서드도 오버라이딩이 되나요?","오버라이딩할 때 반환 타입이나 접근 제어자는 어떤 제약이 있나요?"]},{"id":"java-03","topic":"Java","level":"하","question":"인터페이스와 추상 클래스는 어떻게 다르고, 언제 각각을 쓰나요?","answer":"추상 클래스는 필드(상태)와 생성자를 가질 수 있지만 클래스는 하나만 상속할 수 있습니다. 인터페이스는 여러 개를 구현할 수 있고 계약(역할)을 정의하며, Java 8부터 default·static 메서드, Java 9부터 private 메서드를 가질 수 있습니다. 상태와 공통 구현을 공유하는 is-a 관계는 추상 클래스, 서로 다른 계층이 공유하는 능력(can-do)은 인터페이스가 적합합니다.","keywords":["다중 구현","default 메서드","상태","단일 상속"],"source":"https://docs.oracle.com/javase/tutorial/java/IandI/abstract.html","followups":["두 인터페이스의 default 메서드 시그니처가 충돌하면 어떻게 하나요?","그럼 상태가 필요 없는데도 추상 클래스를 택할 이유가 있을까요?"]},{"id":"java-04","topic":"Java","level":"하","question":"String이 불변(immutable) 객체인 이유와 String Pool이 무엇인지 설명해 보세요.","answer":"String은 생성 후 내용이 바뀌지 않아 +, replace 같은 연산이 항상 새 객체를 반환합니다. 불변이라 스레드에 안전하고 hashCode를 캐싱할 수 있으며 HashMap 키로 안전하게 쓸 수 있습니다. 문자열 리터럴은 String Pool에서 공유되어 같은 리터럴은 같은 객체를 가리키고, new String(\"a\")은 별도 객체를 만듭니다. intern()은 풀의 대표 객체를 돌려줍니다.","keywords":["불변","String Pool","intern","스레드 안전"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/lang/String.html","followups":["new String(\"a\")와 리터럴 \"a\"는 몇 개의 객체를 만드나요?","불변 객체를 직접 설계한다면 어떤 규칙을 지켜야 하나요?"]},{"id":"java-05","topic":"Java","level":"하","question":"String, StringBuilder, StringBuffer는 각각 언제 쓰나요?","answer":"String은 불변이라 반복 연결 시 객체가 계속 생성되므로 루프 안에서 문자열을 많이 이어 붙이면 비효율적입니다. StringBuilder는 가변이지만 동기화가 없어 단일 스레드에서 빠르고, StringBuffer는 메서드가 동기화되어 있어 스레드 안전하지만 느립니다. 실무에서는 대부분 StringBuilder를 쓰며, StringBuffer를 쓸 일은 드뭅니다.","keywords":["가변","동기화","StringBuilder","성능"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/lang/StringBuilder.html","followups":["컴파일러가 + 연산을 어떻게 처리하기에 단순 연결은 String으로도 충분한가요?","StringBuffer를 요즘 거의 쓰지 않는 이유는 무엇인가요?"]},{"id":"java-06","topic":"Java","level":"하","question":"== 연산자와 equals() 메서드의 차이는 무엇인가요?","answer":"==는 기본형에서는 값을, 참조형에서는 같은 객체(참조 주소)인지를 비교합니다. equals()는 객체의 논리적 동등성을 비교하는 메서드이며 Object의 기본 구현은 ==와 같아서, 값 비교가 필요하면 오버라이딩해야 합니다. String·Integer 등은 equals가 값 비교로 재정의되어 있고, new String(\"a\") == new String(\"a\")는 false지만 equals는 true입니다.","keywords":["참조 비교","논리적 동등성","Object.equals","오버라이딩"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/lang/Object.html#equals(java.lang.Object)","followups":["Integer 값 127과 128을 ==로 비교하면 결과가 다른 이유는 무엇인가요?","equals를 직접 구현할 때 지켜야 할 규약을 말해 보세요."]},{"id":"java-07","topic":"Java","level":"하","question":"체크 예외(checked)와 언체크 예외(unchecked)의 차이를 설명해 보세요.","answer":"체크 예외는 Exception을 상속하되 RuntimeException은 아닌 예외로, 컴파일러가 try-catch 처리나 throws 선언을 강제합니다(IOException 등). 언체크 예외는 RuntimeException과 그 하위, 그리고 Error이며 컴파일러가 처리를 강제하지 않고 주로 프로그래밍 오류(NullPointerException, IllegalArgumentException)를 나타냅니다. 복구 가능성이 있는 상황은 체크 예외, 프로그램 버그는 언체크 예외로 설계하는 것이 일반적입니다.","keywords":["RuntimeException","컴파일러 강제","throws","Error"],"source":"https://docs.oracle.com/javase/tutorial/essential/exceptions/catchOrDeclare.html","followups":["체크 예외를 던지는 메서드를 람다 안에서 쓸 때 생기는 문제는 무엇인가요?","예외를 catch하고 그냥 무시하면 어떤 문제가 생기나요?"]},{"id":"java-08","topic":"Java","level":"하","question":"List, Set, Map의 차이와 대표 구현체를 말해 보세요.","answer":"List는 순서가 있고 중복을 허용하며(ArrayList, LinkedList), Set은 중복을 허용하지 않습니다(HashSet, LinkedHashSet, TreeSet). Map은 키-값 쌍으로 키는 중복될 수 없고(HashMap, LinkedHashMap, TreeMap), Collection 인터페이스를 상속하지 않는 별도 계층입니다. HashSet·HashMap은 순서를 보장하지 않고, LinkedHash*는 삽입 순서, Tree*는 정렬 순서를 유지합니다.","keywords":["순서","중복","키-값","Collection"],"source":"https://docs.oracle.com/javase/tutorial/collections/intro/index.html","followups":["Set이 중복을 판단하는 기준은 구현체마다 어떻게 다른가요?","순서가 보장되는 Map이 필요하면 무엇을 쓰시겠어요?"]},{"id":"java-09","topic":"Java","level":"중","question":"equals()를 오버라이딩할 때 hashCode()도 함께 재정의해야 하는 이유는 무엇인가요?","answer":"규약상 equals()가 true인 두 객체는 hashCode()도 같아야 합니다(역은 성립하지 않아도 됨). equals만 재정의하고 hashCode를 그대로 두면 같은 값의 객체가 서로 다른 해시 버킷에 들어가 HashSet·HashMap에서 중복 저장되거나 get()으로 찾지 못합니다. equals는 반사성·대칭성·추이성·일관성·null 비동등 규약을 지켜야 하고, 둘 다 같은 필드로 구현하며 Objects.equals/Objects.hash나 record를 활용할 수 있습니다.","keywords":["hashCode 규약","HashMap","대칭성","일관성"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/lang/Object.html#hashCode()","followups":["hashCode가 항상 같은 값을 반환하게 구현하면 어떻게 되나요?","HashSet에 넣은 뒤 필드를 바꾸면 어떤 일이 생기나요?"]},{"id":"java-10","topic":"Java","level":"중","question":"HashMap은 내부적으로 어떻게 키-값을 저장하고 충돌을 처리하나요?","answer":"키의 hashCode()로 버킷 인덱스를 구하고, 같은 버킷에 여러 키가 들어오면(충돌) 연결 리스트로 이어 equals()로 키를 구분합니다. Java 8부터는 한 버킷의 노드가 많아지면(구현상 8개 이상, 테이블 크기 64 이상) 트리(red-black tree)로 바꿔 최악의 조회 성능을 O(n)에서 O(log n)으로 줄입니다. 기본 load factor 0.75를 넘으면 용량을 2배로 늘리고 재배치(rehash)하며, null 키 1개를 허용하고 스레드 안전하지 않습니다.","keywords":["해시","버킷","load factor","red-black tree","rehash"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/HashMap.html","followups":["키 객체의 hashCode가 모두 같다면 성능은 어떻게 되나요?","HashMap의 초기 용량을 미리 지정하면 좋은 이유는 무엇인가요?"]},{"id":"java-11","topic":"Java","level":"중","question":"ArrayList와 LinkedList의 차이와 선택 기준을 설명해 보세요.","answer":"ArrayList는 배열 기반이라 인덱스 조회가 O(1)이고 중간 삽입·삭제는 요소를 밀어야 해 O(n)입니다. LinkedList는 이중 연결 리스트라 양 끝 삽입·삭제는 O(1)이지만 인덱스 조회는 처음부터 순회해 O(n)이며 노드 객체 때문에 메모리도 더 씁니다. 캐시 지역성 때문에 실무에서는 대부분 ArrayList가 빠르며, 큐·덱 용도라면 ArrayDeque가 보통 더 낫습니다.","keywords":["배열","이중 연결 리스트","O(1)","O(n)"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/ArrayList.html","followups":["ArrayList의 중간에 삽입하면 내부에서 무슨 일이 일어나나요?","실무에서 LinkedList보다 ArrayList를 더 많이 쓰는 이유는 무엇인가요?"]},{"id":"java-12","topic":"Java","level":"중","question":"HashMap, Hashtable, ConcurrentHashMap은 스레드 안전성 면에서 어떻게 다른가요?","answer":"HashMap은 동기화가 없어 여러 스레드가 수정하면 안전하지 않습니다. Hashtable은 모든 메서드를 synchronized로 감싸 안전하지만 전체가 하나의 락이라 동시성이 낮고 레거시입니다. ConcurrentHashMap은 읽기는 락 없이, 쓰기는 버킷 단위로 CAS·synchronized를 사용해(Java 8 이후) 동시성이 높으며 null 키·값을 허용하지 않습니다. 다만 get 후 put 같은 복합 연산은 putIfAbsent, compute, merge 같은 원자적 메서드로 써야 합니다.","keywords":["synchronized","ConcurrentHashMap","CAS","원자적 연산"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/concurrent/ConcurrentHashMap.html","followups":["ConcurrentHashMap에서 get 후 put을 따로 하면 안전한가요? 대안은 무엇인가요?","Collections.synchronizedMap과는 무엇이 다른가요?"]},{"id":"java-13","topic":"Java","level":"중","question":"try-with-resources는 무엇이고 기존 try-finally와 무엇이 다른가요?","answer":"AutoCloseable을 구현한 자원을 try 괄호에 선언하면 블록이 끝날 때 예외 여부와 관계없이 close()가 자동 호출되며, 여러 자원은 선언의 역순으로 닫힙니다. try-finally에서 본문 예외와 close 예외가 모두 발생하면 본문 예외가 덮어써져 사라지지만, try-with-resources는 close 예외를 suppressed 예외로 붙여 본문 예외를 유지합니다. Java 7에서 도입되었고 Java 9부터 effectively final 변수를 괄호에 바로 쓸 수 있습니다.","keywords":["AutoCloseable","close","suppressed","역순"],"source":"https://docs.oracle.com/javase/tutorial/essential/exceptions/tryResourceClose.html","followups":["close() 중에도 예외가 나면 원래 예외는 어떻게 되나요?","try-with-resources에 직접 만든 클래스를 쓰려면 무엇을 해야 하나요?"]},{"id":"java-14","topic":"Java","level":"중","question":"final, finally, finalize의 차이를 설명하고, finalize를 쓰지 말아야 하는 이유를 말해 보세요.","answer":"final은 변수(재할당 불가)·메서드(오버라이딩 불가)·클래스(상속 불가)에 붙는 키워드이고, finally는 try-catch 뒤에서 예외와 무관하게 실행되는 블록이며, finalize는 GC가 객체를 회수하기 전에 호출될 수 있는 Object의 메서드입니다. finalize는 호출 시점과 실행 여부가 보장되지 않고 성능·안전 문제가 있어 Java 9에서 deprecated, Java 18부터 제거 예정(deprecated for removal)입니다. 자원 정리는 try-with-resources나 Cleaner를 사용합니다.","keywords":["final","finally","finalize deprecated","Cleaner"],"source":"https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/lang/Object.html#finalize()","followups":["finally 안에서 return을 쓰면 어떤 일이 생기나요?","finalize 대신 자원 정리를 어떻게 보장하나요?"]},{"id":"java-15","topic":"Java","level":"중","question":"JVM의 런타임 메모리 영역을 나누어 설명해 보세요.","answer":"힙은 모든 스레드가 공유하며 객체와 배열이 저장되고 GC 대상입니다. 스레드마다 JVM 스택이 있어 메서드 호출 때마다 지역 변수·피연산자를 담은 프레임이 쌓이고, 너무 깊으면 StackOverflowError가 납니다. 클래스 메타데이터와 상수 풀은 메서드 영역에 있으며 HotSpot에서는 Java 8부터 PermGen 대신 네이티브 메모리의 Metaspace를 씁니다. 그 외 스레드별 PC 레지스터와 네이티브 메서드 스택이 있고, 힙이 가득 차면 OutOfMemoryError가 발생합니다.","keywords":["힙","스택","Metaspace","메서드 영역","StackOverflowError"],"source":"https://docs.oracle.com/javase/specs/jvms/se17/html/jvms-2.html#jvms-2.5","followups":["지역 변수와 객체는 각각 어느 영역에 저장되나요?","OutOfMemoryError와 StackOverflowError는 각각 어떤 상황에서 발생하나요?"]},{"id":"java-16","topic":"Java","level":"중","question":"가비지 컬렉션은 어떤 객체를 회수하고, 힙은 왜 Young/Old로 나누나요?","answer":"GC는 GC Root(스레드 스택의 지역 변수, static 필드 등)에서 참조로 도달할 수 없는 객체를 회수합니다. 대부분의 객체는 금방 죽는다는 약한 세대 가설에 따라 힙을 Young(Eden·Survivor)과 Old로 나누고, 새 객체는 Young에 할당해 minor GC로 자주 싸게 정리하며 오래 산 객체는 Old로 승격(promotion)합니다. 정리 중에는 애플리케이션이 멈추는 stop-the-world가 발생하며, Java 17·21 서버 환경의 기본 수집기는 G1입니다.","keywords":["GC Root","Young/Old","minor GC","stop-the-world","G1"],"source":"https://docs.oracle.com/en/java/javase/17/gctuning/garbage-collector-implementation.html","followups":["어떤 경우에 객체가 Old 영역으로 넘어가나요?","stop-the-world 시간을 줄이려면 어떤 접근이 있나요?"]},{"id":"java-17","topic":"Java","level":"중","question":"자바에서 스레드를 만드는 방법과 start()와 run()의 차이를 설명해 보세요.","answer":"Thread를 상속하거나 Runnable(또는 람다)을 Thread에 전달해 만들고, 실무에서는 ExecutorService 같은 스레드 풀을 주로 씁니다. start()는 새 스레드를 만들어 그 스레드에서 run()이 실행되게 하고, run()을 직접 호출하면 새 스레드 없이 현재 스레드에서 일반 메서드처럼 실행됩니다. 한 Thread에 start()를 두 번 호출하면 IllegalThreadStateException이 발생합니다.","keywords":["Runnable","start","run","ExecutorService"],"source":"https://docs.oracle.com/javase/tutorial/essential/concurrency/runthread.html","followups":["run()을 직접 호출하면 어떤 일이 일어나나요?","스레드를 직접 만들지 않고 ExecutorService를 쓰는 이유는 무엇인가요?"]},{"id":"java-18","topic":"Java","level":"중","question":"synchronized와 volatile은 각각 무엇을 보장하고 어떻게 다른가요?","answer":"synchronized는 한 번에 한 스레드만 임계 영역에 들어가게 하는 상호 배제(원자성)와, 락 해제 시점의 변경이 다음 획득 스레드에 보이는 가시성을 함께 보장합니다. volatile은 변수의 읽기·쓰기가 항상 메인 메모리 기준으로 보이게 하는 가시성과 순서를 보장하지만 count++ 같은 복합 연산의 원자성은 보장하지 않습니다. 단순 카운터는 AtomicInteger를, 여러 변수를 묶는 임계 영역은 synchronized나 Lock을 사용합니다.","keywords":["가시성","원자성","상호 배제","AtomicInteger"],"source":"https://docs.oracle.com/javase/tutorial/essential/concurrency/atomic.html","followups":["volatile 변수에 count++를 하면 안전한가요? 왜인가요?","synchronized를 메서드에 쓸 때와 블록에 쓸 때 락 대상은 각각 무엇인가요?"]},{"id":"java-19","topic":"Java","level":"중","question":"람다식과 함수형 인터페이스는 무엇이며, 람다에서 지역 변수를 쓸 때의 제약은 무엇인가요?","answer":"함수형 인터페이스는 추상 메서드가 정확히 하나인 인터페이스(Runnable, Comparator, Function 등)이고, 람다식은 그 구현을 간결하게 쓰는 익명 함수 표현입니다. 람다가 바깥 지역 변수를 사용하려면 그 변수가 final이거나 값이 바뀌지 않는 effectively final이어야 합니다. 람다 안의 this는 람다를 감싼 클래스를 가리키며, 익명 클래스와 달리 자신만의 this를 만들지 않습니다.","keywords":["함수형 인터페이스","effectively final","추상 메서드 1개","this"],"source":"https://docs.oracle.com/javase/tutorial/java/javaOO/lambdaexpressions.html","followups":["익명 클래스와 람다에서 this가 가리키는 대상은 어떻게 다른가요?","람다가 외부 지역 변수를 수정하지 못하게 한 이유는 무엇인가요?"]},{"id":"java-20","topic":"Java","level":"중","question":"Stream의 중간 연산과 최종 연산은 무엇이고, 지연 평가란 무엇인가요?","answer":"filter·map·sorted 같은 중간 연산은 새 Stream을 반환하며 파이프라인만 구성하고, collect·forEach·reduce·count 같은 최종 연산이 호출될 때 비로소 요소가 처리되는 것을 지연 평가라 합니다. Stream은 원본 컬렉션을 변경하지 않으며 한 번 소비하면 재사용할 수 없어 다시 쓰면 IllegalStateException이 납니다. 반복마다 상태를 바꾸는 부수 효과는 피해야 하고, Java 16부터는 stream.toList()로 불변 리스트를 바로 얻을 수 있습니다.","keywords":["중간 연산","최종 연산","지연 평가","일회용"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/stream/package-summary.html","followups":["peek이나 map 안에 로그를 넣었는데 출력되지 않는다면 왜 그럴까요?","이미 소비한 Stream을 다시 쓰면 어떻게 되나요?"]},{"id":"java-21","topic":"Java","level":"상","question":"자바 메모리 모델(JMM)에서 happens-before 관계란 무엇이며 어떤 경우에 성립하나요?","answer":"happens-before는 한 동작의 결과가 다른 동작에 반드시 보이도록 보장하는 순서 관계로, 이것이 없으면 컴파일러·CPU의 재정렬과 캐시 때문에 다른 스레드가 오래된 값을 볼 수 있습니다(데이터 레이스). 같은 모니터의 unlock → 이후 lock, volatile 변수의 쓰기 → 이후 읽기, Thread.start() 이전 동작 → 시작된 스레드의 동작, 스레드 종료 → join() 반환, 한 스레드 내 프로그램 순서 등이 대표적입니다. 이 관계는 추이적이어서 연쇄될 수 있습니다.","keywords":["happens-before","재정렬","volatile","모니터 락","데이터 레이스"],"source":"https://docs.oracle.com/javase/specs/jls/se17/html/jls-17.html#jls-17.4.5","followups":["happens-before가 없으면 어떤 버그가 생길 수 있나요?","스레드 start와 join은 happens-before와 어떤 관계인가요?"]},{"id":"java-22","topic":"Java","level":"상","question":"데드락은 어떤 조건에서 발생하고, 코드에서 어떻게 예방하나요?","answer":"둘 이상의 스레드가 서로가 가진 락을 영원히 기다리는 상태로, 일반적으로 상호 배제·점유 대기·비선점·순환 대기 네 조건이 모두 만족될 때 생깁니다. 가장 흔한 예방법은 모든 스레드가 락을 같은 순서로 획득해 순환 대기를 없애는 것이며, tryLock에 타임아웃을 두거나 락 범위를 줄이고 가능하면 불변 객체·동시성 컬렉션을 쓰는 방법도 있습니다. 발생 후에는 jstack 스레드 덤프에서 deadlock 정보를 확인할 수 있습니다.","keywords":["순환 대기","락 순서","tryLock","jstack"],"source":"https://docs.oracle.com/javase/tutorial/essential/concurrency/deadlock.html","followups":["운영 중 데드락이 의심될 때 어떻게 확인하시겠어요?","락 순서를 통일하기 어려운 구조라면 어떻게 방어하나요?"]},{"id":"java-23","topic":"Java","level":"상","question":"G1 GC와 ZGC는 어떤 목표로 설계되었고 Java 17/21에서 어떻게 선택하나요?","answer":"G1은 힙을 같은 크기의 리전으로 나눠 쓰레기가 많은 리전부터 수집하며, 처리량과 목표 일시 정지 시간(-XX:MaxGCPauseMillis)의 균형을 노리는 Java 9 이후 기본 수집기입니다. ZGC는 대부분의 작업을 애플리케이션과 동시에 수행해 큰 힙에서도 일시 정지를 매우 짧게(밀리초 이하 목표) 유지하는 저지연 수집기이며 Java 15에서 정식이 되었습니다. Java 21에서는 세대별 ZGC를 -XX:+ZGenerational로 선택할 수 있고, 일반 서비스는 G1, 지연에 민감하고 힙이 크면 ZGC를 측정 후 선택합니다.","keywords":["G1","ZGC","리전","일시 정지","저지연"],"source":"https://docs.oracle.com/en/java/javase/21/gctuning/available-collectors.html","followups":["처리량이 중요한 배치와 지연이 중요한 API 서버에서 선택이 어떻게 달라지나요?","GC 로그에서 무엇을 보고 튜닝 필요성을 판단하나요?"]},{"id":"java-24","topic":"Java","level":"상","question":"Java 21의 가상 스레드(virtual thread)는 플랫폼 스레드와 무엇이 다르고 언제 유용한가요?","answer":"플랫폼 스레드는 OS 스레드와 1:1이라 수천 개 이상 만들기 비싸지만, 가상 스레드는 JVM이 관리하는 경량 스레드로 소수의 캐리어(플랫폼) 스레드 위에서 실행되며 블로킹 I/O를 만나면 캐리어에서 내려와 수십만 개도 만들 수 있습니다. Java 21에서 정식 기능이 되었고 요청당 스레드 모델의 I/O 바운드 서버(대기가 많은 작업)에 유용하며 CPU 바운드 작업에는 이점이 없습니다. 풀링하지 않고 작업마다 새로 만들며, Java 21에서는 synchronized 블록 안에서 블로킹하면 캐리어가 고정(pinning)될 수 있어 ReentrantLock 사용을 고려합니다.","keywords":["가상 스레드","캐리어 스레드","I/O 바운드","pinning","Java 21"],"source":"https://docs.oracle.com/en/java/javase/21/core/virtual-threads.html","followups":["synchronized 블록 안에서 블로킹하면 pinning이 왜 문제가 되나요?","CPU 바운드 작업에도 가상 스레드가 유리한가요?"]},{"id":"java-25","topic":"Java","level":"상","question":"제네릭의 타입 소거(type erasure)란 무엇이고, 그로 인한 제약은 무엇인가요?","answer":"컴파일러가 제네릭 타입 정보를 컴파일 시점에 검사한 뒤 바이트코드에서는 지우고(바운드가 없으면 Object로 치환) 필요한 곳에 캐스팅을 삽입하는 방식입니다. 그래서 런타임에는 List<String>과 List<Integer>가 같은 List 클래스이며, new T(), new T[], instanceof List<String>, 기본형 타입 인자(List<int>)를 쓸 수 없습니다. 이 때문에 제네릭 배열 생성이 막혀 있고, 타입 정보가 필요하면 Class<T>를 인자로 넘기거나 와일드카드(PECS: Producer Extends, Consumer Super)를 사용합니다.","keywords":["타입 소거","Object","와일드카드","instanceof","Class<T>"],"source":"https://docs.oracle.com/javase/tutorial/java/generics/erasure.html","followups":["List<String>과 List<Integer>를 런타임에 구분할 수 없는 이유는 무엇인가요?","<? extends T>와 <? super T>는 언제 각각 쓰나요?"]},{"id":"java-26","topic":"Java","level":"하","question":"Optional은 왜 쓰고, 어떻게 쓰면 안 되나요?","answer":"Optional은 값이 없을 수 있음을 반환 타입에 명시해 null 체크 누락(NPE)을 줄이는 컨테이너입니다. orElse·orElseGet·map·ifPresent로 값이 없을 때의 처리를 이어 쓸 수 있고, orElse는 값이 있어도 인자를 항상 평가하지만 orElseGet은 필요할 때만 Supplier를 실행합니다. 공식 API는 Optional을 '결과 없음'을 나타내는 메서드 반환 타입용으로 설계했다고 밝히며, 이에 따라 필드·메서드 파라미터·컬렉션 요소로 쓰는 것은 권장되지 않습니다(관례). 또 isPresent 확인 없는 get() 대신 orElseThrow()처럼 값이 없을 때의 동작을 드러내는 메서드를 씁니다.","keywords":["null 안전","orElse/orElseGet","반환 타입용","get() 주의"],"followups":["orElse와 orElseGet은 어떤 경우에 결과가 달라지나요?","Optional을 엔티티 필드에 쓰지 않는 이유는 무엇인가요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/Optional.html"},{"id":"java-27","topic":"Java","level":"중","question":"Java record는 무엇이고 일반 클래스·Lombok과 어떻게 다른가요?","answer":"record는 불변 데이터를 담는 클래스를 간결하게 선언하는 문법(Java 16 정식)으로, 컴포넌트마다 private final 필드와 접근자, canonical 생성자, equals·hashCode·toString이 자동 생성됩니다. 컴팩트 생성자로 검증 로직을 넣을 수 있고, 다른 클래스를 상속할 수 없으며(인터페이스 구현은 가능) 필드는 불변입니다. Lombok(@Value·@Data)은 어노테이션 처리로 코드를 생성하는 외부 라이브러리인 반면 record는 언어 기능이라 별도 의존성이 없고, setter·상속이 필요하면 일반 클래스를 씁니다. DTO·응답 객체에 적합하지만 기본 생성자와 프록시·가변 필드가 필요한 JPA 엔티티로는 쓰지 않습니다.","keywords":["불변","canonical 생성자","컴팩트 생성자","DTO"],"followups":["record를 JPA 엔티티로 쓸 수 없는 이유는 무엇인가요?","record에서 컬렉션 필드는 정말 불변인가요?"],"source":"https://docs.oracle.com/en/java/javase/17/language/records.html"},{"id":"java-28","topic":"Java","level":"중","question":"Java는 call by value인가요, call by reference인가요?","answer":"Java는 항상 값에 의한 전달(pass by value)입니다. 기본형은 값이 복사되어 넘어가 메서드 안에서 바꿔도 호출한 쪽 변수는 그대로입니다. 참조형도 참조 값이 복사되어 전달되므로, 메서드 안에서 객체의 필드를 바꾸면 호출한 쪽에서도 보이지만, 매개변수에 새 객체를 대입해도 호출한 쪽 참조는 여전히 원래 객체를 가리킵니다.","keywords":["값에 의한 전달","참조 값 복사","필드 변경","재할당"],"followups":["메서드 안에서 매개변수에 새 객체를 대입하면 호출한 쪽은 어떻게 되나요?","불변 객체(String)를 인자로 넘기면 왜 바뀌지 않는 것처럼 보이나요?"],"source":"https://docs.oracle.com/javase/tutorial/java/javaOO/arguments.html"},{"id":"java-29","topic":"Java","level":"하","question":"오토박싱과 언박싱이란 무엇인가요?","answer":"오토박싱은 컴파일러가 int→Integer, double→Double처럼 기본형을 대응하는 래퍼 클래스 객체로 자동 변환하는 것이고, 반대 방향이 언박싱입니다. 컬렉션처럼 객체만 담는 곳에 기본형을 편하게 쓰게 해 주지만, 변환이 숨어 있으므로 반복문 안에서 래퍼 타입을 쓰면 객체 생성 비용이 생길 수 있고, null 래퍼를 언박싱하면 NullPointerException이 납니다.","keywords":["래퍼 클래스","자동 변환","NullPointerException","성능"],"followups":["Integer를 == 로 비교하면 왜 문제가 되나요?","List<int>가 안 되고 List<Integer>만 되는 이유는 무엇인가요?"],"source":"https://docs.oracle.com/javase/tutorial/java/data/autoboxing.html"},{"id":"java-30","topic":"Java","level":"중","question":"Java 직렬화(Serializable)와 serialVersionUID는 무엇이고 주의할 점은 무엇인가요?","answer":"직렬화는 객체를 바이트 스트림으로 바꿔 저장·전송하는 것으로, 클래스가 java.io.Serializable을 구현하면 가능합니다. serialVersionUID는 역직렬화 때 송신·수신 쪽 클래스가 호환되는지 확인하는 버전 번호이며 다르면 InvalidClassException이 납니다. transient 필드는 직렬화에서 제외됩니다. 신뢰할 수 없는 데이터의 역직렬화는 본질적으로 위험하므로 피하고 검증해야 합니다.","keywords":["Serializable","serialVersionUID","transient","InvalidClassException","역직렬화 위험"],"followups":["serialVersionUID를 명시하지 않으면 어떤 문제가 생길 수 있나요?","JSON 같은 다른 직렬화 방식과 비교하면 어떤가요?"],"source":"https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/io/Serializable.html"},{"id":"spring-01","topic":"Spring","level":"하","question":"스프링에서 IoC와 DI는 무엇이고, 왜 쓰나요?","answer":"IoC는 객체 생성과 의존 관계 연결의 제어권을 개발자 코드가 아니라 컨테이너가 가지는 것이고, DI는 그 방식 중 하나로 컨테이너가 의존 객체를 생성자·세터 등으로 주입해 주는 것입니다. 객체 간 결합도가 낮아져 테스트에서 목 객체로 바꾸기 쉽고 유지보수가 편해집니다.","keywords":["IoC","DI","컨테이너","결합도"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/introduction.html","followups":["IoC 컨테이너가 없다면 직접 객체를 만들 때 어떤 불편이 생기나요?","DI가 테스트 작성을 쉽게 만드는 구체적인 예를 들어 주세요."]},{"id":"spring-02","topic":"Spring","level":"하","question":"생성자 주입, 세터 주입, 필드 주입 중 무엇을 권장하며 그 이유는 무엇인가요?","answer":"필수 의존성은 생성자 주입을 권장합니다(Spring Framework 6 문서 기준). 불변으로 둘 수 있고 의존성이 없는 채로 객체가 만들어지는 것을 막으며, 순환 참조도 초기에 드러납니다. 세터 주입은 선택적·재설정 가능한 의존성에 적합합니다. 필드 주입은 이런 이점(불변성, 필수성 보장)을 얻지 못합니다.","keywords":["생성자 주입","필수 의존성","불변","세터 주입"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/dependencies/factory-collaborators.html","followups":["생성자 주입이 순환 참조를 어떻게 드러내 주나요?","의존성이 선택적이라면 어떤 방식을 쓸 수 있나요?"]},{"id":"spring-03","topic":"Spring","level":"하","question":"@Component, @Service, @Repository, @Controller는 어떻게 다른가요?","answer":"모두 컴포넌트 스캔 대상이 되는 스테레오타입 애노테이션이고 @Service·@Repository·@Controller는 @Component의 특수화입니다. 계층의 역할을 드러내고, @Repository는 영속성 계층의 예외 변환 대상 마커이며 @Controller는 웹 요청 핸들러로 인식됩니다.","keywords":["@Component","스테레오타입","컴포넌트 스캔","예외 변환"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/classpath-scanning.html","followups":["@Repository에 붙는 예외 변환은 구체적으로 무엇인가요?","컴포넌트 스캔이 되지 않는 패키지의 클래스는 어떻게 빈으로 등록하나요?"]},{"id":"spring-04","topic":"Spring","level":"하","question":"스프링 빈의 기본 스코프는 무엇이고 어떤 특징이 있나요?","answer":"기본 스코프는 singleton으로, 컨테이너당 빈 정의마다 하나의 인스턴스만 만들어 공유합니다. 여러 스레드가 공유하므로 상태(필드)를 가지면 동기화 문제가 생길 수 있어 무상태로 설계하는 것이 일반적입니다. GoF의 싱글톤 패턴(클래스로더당 하나)과는 범위 개념이 다릅니다.","keywords":["singleton","컨테이너","공유","무상태"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/factory-scopes.html","followups":["싱글톤 빈에 가변 필드를 두면 어떤 문제가 생기나요?","싱글톤이라는 말이 GoF 싱글톤 패턴과 어떻게 다른가요?"]},{"id":"spring-05","topic":"Spring","level":"중","question":"프로토타입 스코프를 포함해 스프링의 빈 스코프 종류를 설명해 주세요.","answer":"singleton(기본), prototype(요청할 때마다 새 인스턴스)이 있고 웹 환경에서는 request, session, application, websocket 스코프가 추가됩니다. prototype은 컨테이너가 생성·의존성 주입·조립까지만 하고 이후 생명주기를 관리하지 않아, 소멸 콜백이 자동 호출되지 않습니다.","keywords":["singleton","prototype","request","session"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/factory-scopes.html","followups":["request 스코프 빈을 싱글톤 빈에서 쓰려면 어떻게 해야 하나요?","prototype 빈의 소멸 콜백은 누가 호출하나요?"]},{"id":"spring-06","topic":"Spring","level":"중","question":"BeanFactory와 ApplicationContext의 차이는 무엇인가요?","answer":"BeanFactory는 빈 생성·조회의 기본 기능을 제공하는 인터페이스이고, ApplicationContext는 그 하위 인터페이스로 메시지 국제화(MessageSource), 이벤트 발행(ApplicationEvent), 리소스 로딩, AOP 통합 등을 더한 것입니다. 일반 애플리케이션에서는 ApplicationContext를 사용하며 싱글톤 빈을 기동 시점에 미리 생성합니다.","keywords":["BeanFactory","ApplicationContext","MessageSource","이벤트"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/context-introduction.html","followups":["일반적으로 BeanFactory를 직접 쓰지 않는 이유는 무엇인가요?","ApplicationContext의 이벤트 기능은 어떤 용도로 쓸 수 있나요?"]},{"id":"spring-07","topic":"Spring","level":"중","question":"빈의 초기화·소멸 콜백에는 어떤 방법이 있고 실행 순서는 어떤가요?","answer":"초기화는 @PostConstruct, InitializingBean.afterPropertiesSet(), 설정한 init-method(@Bean의 initMethod) 세 가지가 있고 이 순서로 호출됩니다. 소멸은 @PreDestroy, DisposableBean.destroy(), destroy-method 순서입니다. 스프링 인터페이스에 종속되지 않는 @PostConstruct/@PreDestroy를 권장합니다.","keywords":["@PostConstruct","afterPropertiesSet","init-method","@PreDestroy"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/factory-nature.html","followups":["@PostConstruct와 afterPropertiesSet이 함께 있으면 어느 쪽이 먼저 실행되나요?","초기화 콜백에서 외부 호출 같은 무거운 작업을 하면 어떤 문제가 있나요?"]},{"id":"spring-08","topic":"Spring","level":"상","question":"BeanPostProcessor와 BeanFactoryPostProcessor는 무엇이 다른가요?","answer":"BeanFactoryPostProcessor는 빈 인스턴스가 만들어지기 전에 빈 정의(메타데이터)를 읽거나 수정합니다. BeanPostProcessor는 빈이 인스턴스화된 뒤 초기화 콜백 전후(postProcessBeforeInitialization/AfterInitialization)에 빈 객체를 가공하거나 프록시로 교체할 수 있으며, AOP 프록시 생성이 이 방식으로 이뤄집니다.","keywords":["BeanFactoryPostProcessor","BeanPostProcessor","빈 정의","프록시"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/factory-extension.html","followups":["AOP 프록시는 어느 단계에서 만들어지나요?","BeanFactoryPostProcessor로 할 수 있는 작업의 예를 들어 보세요."]},{"id":"spring-09","topic":"Spring","level":"상","question":"싱글톤 빈이 프로토타입 빈을 주입받으면 어떤 문제가 생기고 어떻게 해결하나요?","answer":"싱글톤 빈은 한 번만 생성·주입되므로 주입된 프로토타입 빈도 그때 만들어진 인스턴스 하나로 고정되어, 매번 새 인스턴스를 얻지 못합니다. 필요할 때마다 새 인스턴스를 얻으려면 ObjectProvider(또는 ApplicationContext.getBean)나 scoped proxy 등을 사용합니다.","keywords":["싱글톤","프로토타입","ObjectProvider","scoped proxy"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/factory-scopes.html#beans-factory-scopes-sing-prot-interaction","followups":["ObjectProvider와 scoped proxy는 각각 어떤 상황에 어울리나요?","그냥 싱글톤 빈 안에서 new로 만들면 안 되는 이유는 무엇인가요?"]},{"id":"spring-10","topic":"Spring","level":"중","question":"@Configuration 클래스에서 @Bean 메서드 간 호출이 싱글톤을 보장하는 원리는 무엇인가요?","answer":"@Configuration 클래스는 CGLIB으로 서브클래싱된 프록시로 처리되어, @Bean 메서드를 다른 @Bean 메서드에서 호출해도 컨테이너가 기존 빈을 반환하는 inter-bean 참조가 동작합니다. @Configuration(proxyBeanMethods = false)로 두면 프록시를 만들지 않아 그 보장이 사라지고 호출마다 새 객체가 만들어질 수 있습니다.","keywords":["@Configuration","@Bean","CGLIB","proxyBeanMethods"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/beans/java/configuration-annotation.html","followups":["proxyBeanMethods = false를 쓰면 무엇이 달라지고 언제 쓰나요?","@Configuration 없이 @Component에서 @Bean을 쓰면 어떻게 되나요?"]},{"id":"spring-11","topic":"Spring","level":"하","question":"AOP의 핵심 용어(Aspect, Join point, Pointcut, Advice)를 설명해 주세요.","answer":"Aspect는 여러 클래스에 걸친 관심사(로깅·트랜잭션 등)를 모듈화한 것, Join point는 실행 중 끼어들 수 있는 지점(스프링 AOP에서는 메서드 실행), Pointcut은 어떤 join point에 적용할지 고르는 표현식, Advice는 그 지점에서 실제 실행되는 부가 로직입니다. Target object는 advice가 적용되는 대상 객체입니다.","keywords":["Aspect","Join point","Pointcut","Advice"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/aop/introduction-defn.html","followups":["Pointcut 표현식에서 execution은 어떤 식으로 쓰나요?","Spring AOP가 지원하는 Join point는 어떤 범위로 제한되나요?"]},{"id":"spring-12","topic":"Spring","level":"중","question":"Spring AOP의 Advice 종류와 @Around의 특징을 설명해 주세요.","answer":"@Before, @AfterReturning, @AfterThrowing, @After(finally와 유사하게 정상·예외 모두), @Around가 있습니다. @Around는 ProceedingJoinPoint.proceed()로 대상 메서드 호출 여부와 시점을 직접 제어하며 반환값·예외도 바꿀 수 있어 가장 강력합니다. 필요한 기능만 가진 가장 약한 advice를 쓰는 것이 좋습니다.","keywords":["@Before","@AfterReturning","@Around","proceed"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/aop/ataspectj/advice.html","followups":["@Around에서 proceed()를 호출하지 않으면 어떻게 되나요?","@After와 @AfterReturning은 무엇이 다른가요?"]},{"id":"spring-13","topic":"Spring","level":"중","question":"Spring AOP는 어떤 방식으로 구현되나요? JDK 동적 프록시와 CGLIB의 차이도 말해 주세요.","answer":"런타임에 프록시 객체를 만들어 호출을 가로채는 프록시 기반 AOP입니다. 대상이 인터페이스를 구현하면 JDK 동적 프록시를 쓰고, 그렇지 않으면 CGLIB으로 클래스를 상속한 프록시를 만듭니다. CGLIB은 상속 기반이라 final 클래스·메서드에는 적용되지 않습니다.","keywords":["프록시","JDK 동적 프록시","CGLIB","final"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/aop/proxying.html","followups":["인터페이스가 있는 클래스에도 CGLIB을 쓰게 되는 경우가 있나요?","final 클래스나 final 메서드에는 CGLIB 프록시가 왜 문제인가요?"]},{"id":"spring-14","topic":"Spring","level":"상","question":"같은 클래스 안에서 this로 호출한 메서드에는 @Transactional이나 AOP가 왜 적용되지 않나요?","answer":"프록시 기반 AOP에서는 외부에서 프록시를 거쳐 호출될 때만 advice가 실행됩니다. 같은 객체 내부의 메서드 호출(self-invocation)은 프록시가 아니라 실제 target 객체의 this로 직접 가므로 advice가 실행되지 않습니다. 해결은 로직을 별도 빈으로 분리하는 것이 가장 일반적이며, AspectJ 위빙을 쓰는 방법도 있습니다.","keywords":["self-invocation","프록시","this","별도 빈"],"source":"https://docs.spring.io/spring-framework/reference/6.2/core/aop/proxying.html","followups":["self-invocation 문제를 해결하는 방법에는 무엇이 있나요?","메서드를 private으로 만들고 @Transactional을 붙이면 어떻게 되나요?"]},{"id":"spring-15","topic":"Spring","level":"하","question":"@Controller와 @RestController의 차이는 무엇인가요?","answer":"@RestController는 @Controller와 @ResponseBody를 합친 애노테이션입니다. @Controller는 보통 뷰 이름을 반환해 ViewResolver가 화면을 렌더링하고, @RestController는 반환값을 HttpMessageConverter로 응답 본문(JSON 등)에 직접 씁니다.","keywords":["@Controller","@RestController","@ResponseBody","HttpMessageConverter"],"source":"https://docs.spring.io/spring-framework/reference/6.2/web/webmvc/mvc-controller/ann.html","followups":["@Controller에서 JSON을 반환하려면 어떻게 하나요?","HttpMessageConverter는 어떤 기준으로 선택되나요?"]},{"id":"spring-16","topic":"Spring","level":"중","question":"Spring MVC에서 요청이 들어와 응답이 나가기까지 DispatcherServlet의 처리 흐름을 설명해 주세요.","answer":"DispatcherServlet이 프론트 컨트롤러로 요청을 받아 HandlerMapping으로 처리할 핸들러(컨트롤러 메서드)와 인터셉터 체인을 찾고, HandlerAdapter가 핸들러를 호출합니다. 반환 결과가 뷰 이름이면 ViewResolver로 View를 찾아 렌더링하고, @ResponseBody면 메시지 컨버터로 본문을 씁니다. 예외는 HandlerExceptionResolver가 처리합니다.","keywords":["DispatcherServlet","HandlerMapping","HandlerAdapter","ViewResolver"],"source":"https://docs.spring.io/spring-framework/reference/6.2/web/webmvc/mvc-servlet/special-bean-types.html","followups":["HandlerAdapter가 따로 있는 이유는 무엇인가요?","@RestController에서는 ViewResolver 단계가 어떻게 되나요?"]},{"id":"spring-17","topic":"Spring","level":"중","question":"필터(Filter)와 인터셉터(HandlerInterceptor)의 차이는 무엇인가요?","answer":"필터는 서블릿 스펙(Jakarta Servlet)의 기능으로 DispatcherServlet 앞단에서 동작하고, 인터셉터는 스프링 MVC 안에서 핸들러 매핑 이후 컨트롤러 호출 전후에 동작합니다. 인터셉터는 preHandle, postHandle, afterCompletion 훅과 핸들러 정보에 접근할 수 있습니다. 인코딩·보안 같은 요청 전반은 필터, 컨트롤러 단위 공통 처리는 인터셉터가 적합합니다.","keywords":["필터","인터셉터","preHandle","DispatcherServlet"],"source":"https://docs.spring.io/spring-framework/reference/6.2/web/webmvc/mvc-servlet/handlermapping-interceptor.html","followups":["인증 처리를 필터와 인터셉터 중 어디에 두겠나요? 이유는요?","인터셉터의 preHandle, postHandle, afterCompletion은 언제 각각 호출되나요?"]},{"id":"spring-18","topic":"Spring","level":"중","question":"컨트롤러에서 발생한 예외를 전역으로 처리하려면 어떻게 하나요?","answer":"@ControllerAdvice(또는 @RestControllerAdvice) 클래스에 @ExceptionHandler 메서드를 두면 모든 컨트롤러의 예외를 한곳에서 처리하고 상태 코드와 응답 본문을 정할 수 있습니다. 컨트롤러 내부에 둔 @ExceptionHandler는 그 컨트롤러에만 적용됩니다.","keywords":["@ControllerAdvice","@ExceptionHandler","모든 컨트롤러","응답 본문"],"source":"https://docs.spring.io/spring-framework/reference/6.2/web/webmvc/mvc-controller/ann-exceptionhandler.html","followups":["@ExceptionHandler가 여러 개 매치되면 어떤 것이 선택되나요?","예외 응답 형식을 통일하려면 어떻게 설계하시겠어요?"]},{"id":"spring-19","topic":"Spring","level":"하","question":"@Transactional은 어떻게 동작하나요?","answer":"선언적 트랜잭션은 AOP 프록시 기반으로, 프록시가 메서드 호출 전에 트랜잭션을 시작하고 정상 종료면 커밋, 롤백 대상 예외면 롤백합니다. 보통 public 메서드에 붙이며(6.0부터 클래스 기반 프록시는 protected·package-visible도 기본 적용, 인터페이스 기반 프록시는 public만), 같은 클래스 내부 호출에는 적용되지 않습니다. 트랜잭션 매니저(예: JpaTransactionManager)가 실제 트랜잭션을 관리합니다.","keywords":["프록시","커밋","롤백","public"],"source":"https://docs.spring.io/spring-framework/reference/6.2/data-access/transaction/declarative/annotations.html","followups":["@Transactional을 클래스에 붙일 때와 메서드에 붙일 때 차이는 무엇인가요?","트랜잭션이 실제로 걸렸는지 어떻게 확인하나요?"]},{"id":"spring-20","topic":"Spring","level":"중","question":"@Transactional에서 기본 롤백 규칙은 무엇인가요? 체크 예외는 어떻게 되나요?","answer":"기본적으로 RuntimeException과 Error가 발생하면 롤백하고, 체크 예외는 롤백하지 않고 커밋합니다. 체크 예외에서도 롤백하려면 rollbackFor를 지정하고, 반대로 롤백하지 않을 예외는 noRollbackFor로 지정합니다.","keywords":["RuntimeException","체크 예외","rollbackFor","커밋"],"source":"https://docs.spring.io/spring-framework/reference/6.2/data-access/transaction/declarative/rolling-back.html","followups":["체크 예외가 발생해도 롤백하려면 어떻게 설정하나요?","예외를 catch해서 삼키면 트랜잭션은 어떻게 되나요?"]},{"id":"spring-21","topic":"Spring","level":"상","question":"트랜잭션 전파 속성 REQUIRED와 REQUIRES_NEW의 차이를 설명해 주세요.","answer":"REQUIRED(기본값)는 기존 트랜잭션이 있으면 참여하고 없으면 새로 만들며, 여러 메서드가 논리적 트랜잭션 하나를 공유해 한 곳에서 롤백되면 전체 물리 트랜잭션이 롤백됩니다. REQUIRES_NEW는 항상 독립된 새 물리 트랜잭션을 시작하고 기존 것은 보류해, 안쪽 커밋·롤백이 바깥과 별개입니다. 안쪽에서 새 커넥션이 필요해 풀 고갈 위험이 있습니다.","keywords":["REQUIRED","REQUIRES_NEW","물리 트랜잭션","롤백"],"source":"https://docs.spring.io/spring-framework/reference/6.2/data-access/transaction/declarative/tx-propagation.html","followups":["REQUIRES_NEW 안쪽이 롤백되면 바깥 트랜잭션은 어떻게 되나요?","REQUIRED로 묶인 안쪽 메서드에서 예외가 나면 바깥은 어떻게 되나요?"]},{"id":"spring-22","topic":"Spring","level":"중","question":"트랜잭션 격리 수준에는 무엇이 있고 스프링의 기본값은 무엇인가요?","answer":"Isolation enum에 READ_UNCOMMITTED, READ_COMMITTED, REPEATABLE_READ, SERIALIZABLE과 DEFAULT가 있고, 높을수록 dirty read·non-repeatable read·phantom read를 더 막지만 동시성은 낮아집니다. 스프링의 기본값은 DEFAULT로 사용하는 DB의 기본 격리 수준을 따르므로 DB마다 다를 수 있습니다.","keywords":["READ_COMMITTED","REPEATABLE_READ","SERIALIZABLE","DEFAULT"],"source":"https://docs.spring.io/spring-framework/docs/6.2.x/javadoc-api/org/springframework/transaction/annotation/Isolation.html","followups":["REPEATABLE_READ에서도 팬텀 리드가 발생할 수 있나요?","격리 수준을 높이면 어떤 비용이 생기나요?"]},{"id":"spring-23","topic":"Spring","level":"하","question":"@SpringBootApplication은 어떤 애노테이션들로 이루어져 있나요?","answer":"@SpringBootConfiguration(설정 클래스, @Configuration 계열), @EnableAutoConfiguration(자동 설정 활성화), @ComponentScan(해당 패키지 하위 컴포넌트 스캔)을 합친 것입니다.","keywords":["@SpringBootConfiguration","@EnableAutoConfiguration","@ComponentScan"],"source":"https://docs.spring.io/spring-boot/3.5/reference/using/using-the-springbootapplication-annotation.html","followups":["@ComponentScan의 기본 스캔 범위는 어디까지인가요?","메인 클래스 위치가 중요한 이유는 무엇인가요?"]},{"id":"spring-24","topic":"Spring","level":"상","question":"Spring Boot 3의 자동 설정(Auto-configuration)은 어떤 원리로 동작하나요?","answer":"@EnableAutoConfiguration이 클래스패스의 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports 파일에 나열된 @AutoConfiguration 클래스들을 로드합니다. 각 클래스는 @ConditionalOnClass 같은 조건부 애노테이션으로 클래스패스·빈 존재 여부에 따라 적용되고, 개발자가 직접 정의한 빈이 있으면 물러납니다. exclude나 --debug 리포트로 제어·확인합니다.","keywords":["@EnableAutoConfiguration","AutoConfiguration.imports","@ConditionalOnClass","exclude"],"source":"https://docs.spring.io/spring-boot/3.5/reference/features/developing-auto-configuration.html","followups":["자동 설정된 빈을 내가 직접 정의한 빈으로 바꾸려면 어떻게 하나요?","어떤 자동 설정이 적용됐는지 확인하는 방법은 무엇인가요?"]},{"id":"spring-25","topic":"Spring","level":"중","question":"Spring Boot에서 프로파일과 외부 설정의 우선순위는 어떻게 되나요?","answer":"spring.profiles.active로 활성 프로파일을 정하고 @Profile이나 application-{profile}.properties로 환경별 빈·설정을 나눕니다. 외부 설정은 정해진 PropertySource 순서를 따르며 뒤의 소스가 앞의 값을 덮어씁니다. 예컨대 application.properties보다 환경 변수, 환경 변수보다 커맨드라인 인자가 우선합니다.","keywords":["spring.profiles.active","@Profile","application.properties","커맨드라인"],"source":"https://docs.spring.io/spring-boot/3.5/reference/features/external-config.html","followups":["운영 환경의 DB 비밀번호는 어떻게 주입하는 것이 좋나요?","같은 설정이 properties와 환경 변수에 모두 있으면 어느 쪽이 이기나요?"]},{"id":"spring-26","topic":"Spring","level":"중","question":"Spring Security는 요청을 어떻게 처리하나요? 필터 체인 구조를 설명해 보세요.","answer":"Spring Security는 서블릿 필터 기반으로 동작합니다. 컨테이너의 DelegatingFilterProxy가 스프링 빈인 FilterChainProxy에 위임하고, FilterChainProxy가 요청에 맞는 SecurityFilterChain(필터 목록)을 골라 순서대로 실행합니다. 인증 결과는 SecurityContextHolder의 SecurityContext에 저장되어 이후 인가 판단과 컨트롤러에서 사용됩니다. 그래서 인증·인가 로직은 DispatcherServlet 이전 단계에서 처리됩니다.","keywords":["DelegatingFilterProxy","FilterChainProxy","SecurityFilterChain","SecurityContextHolder"],"followups":["JWT 인증 필터는 보통 필터 체인의 어디에 추가하나요?","인증 실패와 인가 실패는 각각 어떤 응답으로 처리되나요?"],"source":"https://docs.spring.io/spring-security/reference/servlet/architecture.html"},{"id":"spring-27","topic":"Spring","level":"중","question":"@SpringBootTest, @WebMvcTest, @DataJpaTest는 어떻게 다르고 언제 쓰나요?","answer":"@SpringBootTest는 전체 애플리케이션 컨텍스트를 띄워 통합 테스트를 하므로 느리지만 실제 구성에 가깝습니다. @WebMvcTest는 컨트롤러 등 웹 계층만 로드하고 MockMvc로 요청을 검증하며, 서비스는 목 빈으로 대체합니다(Boot 3.4+는 @MockitoBean). @DataJpaTest는 JPA 관련 빈만 로드해 리포지토리 테스트에 쓰며 테스트마다 트랜잭션을 롤백합니다. 필요한 범위만 띄우는 슬라이스 테스트가 빠르고 원인 파악이 쉽습니다.","keywords":["통합 테스트","슬라이스 테스트","MockMvc","롤백"],"followups":["서비스 계층 단위 테스트는 스프링 컨텍스트 없이 어떻게 작성하나요?","@DataJpaTest가 기본으로 내장 DB를 쓰는 이유와 바꾸는 방법은 무엇인가요?"],"source":"https://docs.spring.io/spring-boot/reference/testing/spring-boot-applications.html"},{"id":"jpa-01","topic":"JPA","level":"하","question":"영속성 컨텍스트가 무엇이고 어떤 역할을 하는지 설명해 보세요.","answer":"영속성 컨텍스트는 엔티티를 영구 저장하고 관리하는 논리적 공간으로, EntityManager를 통해 접근합니다. 같은 식별자의 엔티티는 컨텍스트 안에서 하나의 인스턴스로 관리(1차 캐시·동일성 보장)되고, 변경 사항은 flush 시점에 SQL로 반영됩니다. 일반적으로 트랜잭션 범위와 함께 생성·종료됩니다(Spring 기본 설정 기준).","keywords":["영속성 컨텍스트","EntityManager","1차 캐시","flush"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["같은 id로 두 번 find하면 쿼리가 몇 번 나가나요?","영속성 컨텍스트가 트랜잭션 범위를 벗어나면 어떤 일이 생기나요?"]},{"id":"jpa-02","topic":"JPA","level":"하","question":"JPA 엔티티의 생명주기 상태 네 가지를 설명해 보세요.","answer":"new(transient)는 아직 영속성 컨텍스트와 무관한 새 객체이고, managed(persistent)는 컨텍스트가 관리하는 상태입니다. detached는 한때 관리되다가 컨텍스트가 닫히거나 detach/clear로 분리된 상태이며, removed는 삭제가 예약되어 flush/커밋 시 DELETE가 실행될 상태입니다. persist로 managed, remove로 removed, merge로 detached 상태 데이터를 다시 반영합니다.","keywords":["new","managed","detached","removed"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["detached 엔티티는 어떤 경우에 만들어지나요?","removed 상태의 엔티티는 언제 실제로 DELETE되나요?"]},{"id":"jpa-03","topic":"JPA","level":"하","question":"JPA와 Hibernate는 어떤 관계인가요?","answer":"JPA(Jakarta Persistence)는 ORM을 위한 표준 명세(인터페이스·애노테이션)이고, Hibernate는 그 명세를 구현한 대표적인 구현체입니다. Hibernate 6은 Jakarta Persistence 3.x를 따르며 패키지가 javax.persistence에서 jakarta.persistence로 바뀌었습니다. Spring Data JPA는 이 위에서 Repository 추상화를 제공하는 별도 계층입니다.","keywords":["명세","구현체","jakarta.persistence","Spring Data JPA"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["Hibernate 대신 다른 구현체로 바꿀 수 있나요?","Spring Data JPA는 JPA와 어떤 관계인가요?"]},{"id":"jpa-04","topic":"JPA","level":"하","question":"JPA 엔티티 클래스에 요구되는 조건은 무엇인가요?","answer":"@Entity가 붙어야 하고 @Id로 기본키를 지정해야 합니다. 인자 없는 기본 생성자(public 또는 protected)가 필요하며, 클래스·영속 필드 메서드는 final이면 안 됩니다(프록시 생성 때문). 최상위 클래스여야 하고, 영속 필드는 직접 접근하지 않는 것이 권장됩니다.","keywords":["@Entity","@Id","기본 생성자","final"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["엔티티에 기본 생성자가 필요한 이유는 무엇인가요?","final 클래스나 final 필드가 문제 되는 이유는 무엇인가요?"]},{"id":"jpa-05","topic":"JPA","level":"하","question":"@ManyToOne과 @OneToMany의 기본 fetch 전략은 무엇이고, 실무에서는 어떻게 설정하나요?","answer":"Jakarta Persistence 명세에서 @ManyToOne·@OneToOne의 기본은 EAGER, @OneToMany·@ManyToMany는 LAZY입니다. EAGER는 예상 못한 추가 쿼리와 N+1을 일으키기 쉬워 실무에서는 모든 연관관계를 LAZY로 두고 필요할 때 fetch join이나 EntityGraph로 함께 조회합니다.","keywords":["EAGER","LAZY","fetch join","N+1"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["실무에서 모두 LAZY로 두고 필요한 곳에서만 fetch join하는 이유는 무엇인가요?","@OneToMany의 기본이 LAZY인 이유를 어떻게 설명하겠어요?"]},{"id":"jpa-06","topic":"JPA","level":"하","question":"지연 로딩(LAZY)과 즉시 로딩(EAGER)의 차이를 설명해 보세요.","answer":"지연 로딩은 연관 엔티티를 실제 사용하는 시점에 조회하고 그 전까지는 프록시(또는 지연 컬렉션)를 둡니다. 즉시 로딩은 엔티티를 조회할 때 연관 엔티티를 함께 로딩합니다. LAZY는 영속성 컨텍스트가 닫힌 뒤 접근하면 LazyInitializationException이 발생할 수 있습니다.","keywords":["프록시","지연 로딩","즉시 로딩","LazyInitializationException"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["LAZY일 때 연관 객체의 실체는 무엇인가요?","즉시 로딩이 N+1을 일으키는 과정을 설명해 보세요."]},{"id":"jpa-07","topic":"JPA","level":"하","question":"@Enumerated에서 EnumType.ORDINAL 대신 STRING을 권장하는 이유는 무엇인가요?","answer":"ORDINAL은 enum 선언 순서(0, 1, 2…)를 숫자로 저장하므로 enum 상수를 중간에 추가하거나 순서를 바꾸면 기존 데이터의 의미가 어긋납니다. STRING은 상수 이름을 저장해 순서 변경에 안전하지만 이름을 바꾸면 마이그레이션이 필요하고 저장 공간을 더 씁니다. @Enumerated를 생략하면 기본이 ORDINAL이라는 점도 주의해야 합니다.","keywords":["ORDINAL","STRING","순서","@Enumerated"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["이미 ORDINAL로 운영 중인 데이터가 있다면 어떻게 마이그레이션하나요?","STRING을 쓰더라도 enum 이름을 바꾸면 어떤 문제가 있나요?"]},{"id":"jpa-08","topic":"JPA","level":"하","question":"flush는 언제 발생하고 무엇을 하나요?","answer":"flush는 영속성 컨텍스트의 변경 내용(쓰기 지연 SQL)을 DB에 동기화하는 작업이며 커밋은 아닙니다. 기본 FlushModeType.AUTO에서는 트랜잭션 커밋 직전과, 변경이 반영돼야 결과가 맞는 쿼리(JPQL 등) 실행 전에 자동 발생하고, em.flush()로 직접 호출할 수도 있습니다. flush 후에도 영속성 컨텍스트는 유지되고 롤백도 가능합니다.","keywords":["flush","FlushModeType.AUTO","커밋","쓰기 지연"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["JPQL 실행 전에 flush가 자동으로 일어나는 이유는 무엇인가요?","flush와 commit은 어떻게 다른가요?"]},{"id":"jpa-09","topic":"JPA","level":"중","question":"연관관계의 주인(owning side)이란 무엇이고 mappedBy는 어떤 역할을 하나요?","answer":"양방향 연관관계에서 외래키를 관리해 DB 반영 여부를 결정하는 쪽이 주인이며, 보통 외래키가 있는 @ManyToOne 쪽입니다. 주인이 아닌 쪽은 mappedBy로 주인 필드명을 지정해 읽기 전용으로 두고, 이쪽만 바꿔서는 외래키가 갱신되지 않습니다. 그래서 객체 상태 일관성을 위해 양쪽에 모두 값을 세팅하는 연관관계 편의 메서드를 둡니다.","keywords":["연관관계 주인","mappedBy","외래키","양방향"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["주인이 아닌 쪽에만 값을 세팅하면 DB에는 어떻게 저장되나요?","양방향 연관관계에서 편의 메서드를 두는 이유는 무엇인가요?"]},{"id":"jpa-10","topic":"JPA","level":"중","question":"더티 체킹(dirty checking)이 무엇인지 설명해 보세요.","answer":"영속성 컨텍스트는 엔티티를 처음 로딩한 시점의 상태(스냅샷)를 보관하고, flush 때 현재 상태와 비교해 변경된 엔티티에 대해 UPDATE를 자동 생성합니다. 그래서 managed 상태 엔티티는 setter로 값을 바꾸기만 해도 update 호출 없이 트랜잭션 커밋 시 반영됩니다. detached 엔티티는 대상이 아니므로 merge가 필요합니다.","keywords":["스냅샷","flush","UPDATE","managed"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["변경 감지로 UPDATE되는 컬럼을 일부만 나가게 할 수 있나요?","detached 엔티티를 수정하면 DB에 반영되나요?"]},{"id":"jpa-11","topic":"JPA","level":"중","question":"N+1 문제란 무엇이고 왜 발생하나요?","answer":"목록을 조회하는 쿼리 1번 뒤에 각 엔티티의 연관 데이터를 가져오는 쿼리가 N번 추가로 나가는 문제입니다. 연관관계를 LAZY로 두고 반복문에서 접근하거나, EAGER 연관을 JPQL로 조회할 때 JPQL이 연관 로딩을 따로 처리해 발생합니다. 데이터가 많아질수록 쿼리 수가 늘어 성능이 급격히 나빠집니다.","keywords":["N+1","LAZY","JPQL","쿼리 수"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["연관관계 100건을 조회하면 쿼리가 몇 번 나가나요?","N+1 문제를 로그에서 어떻게 발견하나요?"]},{"id":"jpa-12","topic":"JPA","level":"중","question":"N+1 문제를 해결하는 방법을 설명해 보세요.","answer":"JPQL의 join fetch로 연관 엔티티를 한 번의 쿼리로 함께 가져오는 것이 가장 일반적입니다. Spring Data JPA에서는 @EntityGraph로 같은 효과를 낼 수 있고, hibernate.default_batch_fetch_size나 @BatchSize를 쓰면 IN 절로 묶어 N번을 소수의 쿼리로 줄입니다. 컬렉션 fetch join은 페이징 한계가 있어 상황에 맞게 선택합니다.","keywords":["fetch join","@EntityGraph","batch size","IN 절"],"source":"https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html","followups":["fetch join과 @EntityGraph는 무엇이 다른가요?","batch size를 쓰면 쿼리가 어떻게 바뀌나요?"]},{"id":"jpa-13","topic":"JPA","level":"중","question":"JPQL은 SQL과 무엇이 다르고, 네이티브 쿼리는 언제 쓰나요?","answer":"JPQL은 테이블이 아니라 엔티티와 필드를 대상으로 하는 객체지향 쿼리로, 특정 DB 문법에 종속되지 않고 실행 시 SQL로 변환됩니다. 네이티브 쿼리는 DB 고유 기능(윈도 함수, 힌트 등)이 필요하거나 복잡한 통계 쿼리일 때 쓰며, 이식성이 떨어지고 영속성 컨텍스트와 별개로 동작하므로 flush·결과 매핑에 주의합니다.","keywords":["JPQL","엔티티","네이티브 쿼리","이식성"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["JPQL은 왜 테이블이 아닌 엔티티를 대상으로 하나요?","네이티브 쿼리의 결과를 엔티티로 받을 수 있나요?"]},{"id":"jpa-14","topic":"JPA","level":"중","question":"EntityManager의 persist와 merge는 어떻게 다른가요?","answer":"persist는 new 상태 엔티티를 managed로 만들어 그 인스턴스를 그대로 관리합니다. merge는 detached(또는 new) 엔티티의 값을 복사해 managed 복사본을 새로 반환하며, 전달한 원본 인스턴스는 managed가 되지 않습니다. Spring Data JPA의 save()는 isNew 판정에 따라 persist 또는 merge를 호출합니다.","keywords":["persist","merge","detached","save()"],"source":"https://docs.spring.io/spring-data/jpa/reference/jpa/entity-persistence.html","followups":["이미 존재하는 id의 새 객체에 persist를 호출하면 어떻게 되나요?","merge 후 반환된 객체와 전달한 객체는 같은가요?"]},{"id":"jpa-15","topic":"JPA","level":"중","question":"CascadeType과 orphanRemoval은 각각 무엇이고 어떻게 다른가요?","answer":"CascadeType(PERSIST, REMOVE 등)은 부모에 수행한 영속 상태 전이를 연관 엔티티에 전파합니다. orphanRemoval=true는 부모 컬렉션에서 제거되어 고아가 된 자식을 DELETE하며 REMOVE 전파 효과도 함께 가집니다. 자식 라이프사이클을 부모가 전적으로 소유하는 경우에만 쓰고, 여러 곳에서 참조되는 엔티티에는 위험합니다.","keywords":["CascadeType","PERSIST","orphanRemoval","라이프사이클"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["CascadeType.REMOVE와 orphanRemoval의 동작은 어떻게 다른가요?","cascade를 아무 곳에나 쓰면 어떤 위험이 있나요?"]},{"id":"jpa-16","topic":"JPA","level":"중","question":"JPA의 낙관적 락(@Version)은 어떻게 동작하나요?","answer":"엔티티에 @Version 필드를 두면 UPDATE 시 WHERE에 version 조건을 걸고 성공하면 값을 증가시킵니다. 다른 트랜잭션이 먼저 수정했다면 갱신된 행이 없어 OptimisticLockException이 발생하고(Spring에서는 ObjectOptimisticLockingFailureException으로 변환) 재시도 등 처리가 필요합니다. DB 락을 쓰지 않아 충돌이 드문 환경에 적합합니다.","keywords":["@Version","OptimisticLockException","충돌","재시도"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["충돌 시 재시도는 어느 계층에서 하는 게 좋을까요?","@Version 없이 갱신 손실을 막으려면 어떻게 하나요?"]},{"id":"jpa-17","topic":"JPA","level":"중","question":"비관적 락(PESSIMISTIC_WRITE)은 무엇이고 언제 쓰나요?","answer":"조회 시점에 DB에 락을 걸어(대개 SELECT … FOR UPDATE) 다른 트랜잭션의 수정·락 획득을 막습니다. 충돌이 잦거나 재고 차감처럼 실패 재시도 비용이 큰 경우에 쓰며, Spring Data JPA에서는 @Lock(LockModeType.PESSIMISTIC_WRITE)를 쿼리 메서드에 붙입니다. 대기와 데드락 위험이 있어 락 타임아웃과 트랜잭션 범위를 짧게 유지해야 합니다.","keywords":["PESSIMISTIC_WRITE","SELECT FOR UPDATE","@Lock","데드락"],"source":"https://docs.spring.io/spring-data/jpa/reference/jpa/locking.html","followups":["비관적 락의 락 대기 시간은 어떻게 제한하나요?","낙관적 락과 비관적 락 중 충돌이 잦은 환경에는 무엇이 맞나요?"]},{"id":"jpa-18","topic":"JPA","level":"중","question":"Spring Data JPA에서 조회 메서드에 @Transactional(readOnly = true)를 쓰는 이유는 무엇인가요?","answer":"SimpleJpaRepository는 클래스 수준에서 readOnly=true 트랜잭션을 기본으로 사용하고, 쓰기 메서드는 별도 @Transactional로 덮어씁니다. readOnly는 의도를 밝혀 JPA 구현체·드라이버가 최적화(예: Hibernate의 flush 생략으로 더티 체킹 비용 절감)할 힌트를 주지만, 쓰기를 완전히 막는 보장은 아닙니다. 구체 효과는 구현체와 DB에 따라 다릅니다.","keywords":["readOnly","SimpleJpaRepository","트랜잭션","flush"],"source":"https://docs.spring.io/spring-data/jpa/reference/jpa/transactions.html","followups":["readOnly = true가 변경 감지에 어떤 영향을 주나요?","readOnly 트랜잭션 안에서 save를 호출하면 어떻게 되나요?"]},{"id":"jpa-19","topic":"JPA","level":"중","question":"LazyInitializationException은 언제 발생하고 어떻게 해결하나요?","answer":"영속성 컨텍스트(세션)가 닫힌 뒤 초기화되지 않은 LAZY 프록시나 컬렉션에 접근하면 발생합니다. Hibernate 문서는 영속성 컨텍스트를 닫기 전에 필요한 연관을 미리 가져오는 것(fetch join 등)을 최선으로 봅니다. 컬렉션이 여러 개면 join fetch는 한 컬렉션까지만 쓰고 나머지는 보조 쿼리나 Hibernate.initialize로 로딩하며, 실무에서는 트랜잭션 안에서 DTO로 변환해 반환하기도 합니다.","keywords":["LazyInitializationException","세션","fetch join","Hibernate.initialize"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["OSIV(open-in-view)는 이 예외와 어떤 관련이 있나요?","엔티티 대신 DTO로 반환하면 이 문제가 어떻게 줄어드나요?"]},{"id":"jpa-20","topic":"JPA","level":"중","question":"@Embeddable 값 타입과 엔티티의 차이는 무엇인가요?","answer":"엔티티는 @Id로 식별되고 고유한 생명주기를 가지지만, 값 타입은 식별자가 없고 소유 엔티티에 종속되어 함께 저장·삭제됩니다. @Embedded로 필드를 묶어 재사용(예: Address)하며 같은 테이블의 컬럼으로 매핑됩니다. 값 타입은 공유 참조로 인한 부수효과를 막기 위해 불변 객체로 설계하는 것이 좋습니다.","keywords":["@Embeddable","값 타입","식별자","불변"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["@Embeddable 객체를 불변으로 만드는 이유는 무엇인가요?","값 타입의 동등성은 어떻게 비교해야 하나요?"]},{"id":"jpa-21","topic":"JPA","level":"상","question":"GenerationType.IDENTITY 전략이 쓰기 지연과 JDBC 배치에 미치는 영향을 설명해 보세요.","answer":"IDENTITY는 INSERT를 실행해야 DB가 생성한 키를 알 수 있어, persist 시 id를 확보하려고 INSERT가 앞당겨 실행되고 쓰기 지연의 이점이 줄어듭니다. Hibernate 6.4 문서에도 IDENTITY 엔티티는 INSERT 배치를 할 수 없다고 명시되어 있습니다. 배치 삽입이 필요하면 SEQUENCE(allocationSize로 호출 감소)를 고려하며, MySQL은 시퀀스가 없어 IDENTITY나 테이블 방식을 쓰는 경우가 많습니다.","keywords":["IDENTITY","SEQUENCE","쓰기 지연","JDBC 배치"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["IDENTITY에서 persist 시점에 INSERT가 나가는 이유는 무엇인가요?","대량 INSERT가 필요하다면 어떤 전략을 쓰시겠어요?"]},{"id":"jpa-22","topic":"JPA","level":"상","question":"컬렉션 fetch join에 페이징을 적용할 때 어떤 문제가 생기고 어떻게 해결하나요?","answer":"일대다 컬렉션을 fetch join하면 결과 행이 자식 수만큼 늘어나 DB의 LIMIT을 그대로 적용할 수 없어, Hibernate는 경고를 내고 메모리에서 페이징해 OOM 위험이 생깁니다. 해결은 ToOne 관계만 fetch join하고 컬렉션은 default_batch_fetch_size(배치 로딩)로 가져오거나, 먼저 부모 id를 페이징 조회한 뒤 IN으로 자식을 조회하는 방식입니다. 또 List(bag) 컬렉션 둘 이상의 동시 fetch join은 MultipleBagFetchException을 일으킵니다.","keywords":["컬렉션 fetch join","페이징","메모리","default_batch_fetch_size"],"source":"https://docs.jboss.org/hibernate/orm/6.4/userguide/html_single/Hibernate_User_Guide.html","followups":["일대다 fetch join에서 데이터 중복이 생기는 이유는 무엇인가요?","페이징이 필요할 때 ToOne은 fetch join, 컬렉션은 어떻게 하나요?"]},{"id":"jpa-23","topic":"JPA","level":"상","question":"JPQL, Criteria API, QueryDSL을 비교하고 QueryDSL의 장단점을 말해 보세요.","answer":"JPQL은 문자열이라 오타가 런타임에 드러나고, Criteria API는 타입 안전하지만 코드가 장황합니다. QueryDSL은 Q타입 기반 fluent API로 컴파일 타임에 검증되고 동적 쿼리 작성이 쉬워 널리 쓰이지만 Q클래스 생성 설정이 필요하고, 표준 JPA가 아니라 외부 라이브러리입니다. Spring Data 문서에 따르면 Querydsl 유지보수가 둔화되어 OpenFeign 포크가 등장했으니 도입 시 상태를 확인해야 합니다.","keywords":["JPQL","Criteria API","QueryDSL","동적 쿼리"],"source":"https://docs.spring.io/spring-data/commons/reference/repositories/core-extensions.html","followups":["동적 쿼리에서 QueryDSL이 JPQL 문자열보다 나은 점은 무엇인가요?","QueryDSL 도입 시 단점은 무엇인가요?"]},{"id":"jpa-24","topic":"JPA","level":"상","question":"JPA 상속 매핑 전략 세 가지와 각각의 장단점을 설명해 보세요.","answer":"SINGLE_TABLE은 한 테이블에 모두 저장해 조회가 단순하고 빠르지만 자식 전용 컬럼에 null이 많아집니다. JOINED는 부모·자식 테이블을 정규화해 나누어 저장해 구조는 깔끔하나 조회 시 조인이 필요합니다. TABLE_PER_CLASS는 구체 클래스마다 테이블을 두며 다형성 조회 시 UNION이 필요하고 명세상 구현체 지원이 선택적입니다.","keywords":["SINGLE_TABLE","JOINED","TABLE_PER_CLASS","@Inheritance"],"source":"https://jakarta.ee/specifications/persistence/3.1/jakarta-persistence-spec-3.1.html","followups":["SINGLE_TABLE에서 자식 컬럼에 NOT NULL을 걸기 어려운 이유는 무엇인가요?","실무에서는 어떤 전략을 주로 선택하나요?"]},{"id":"jpa-25","topic":"JPA","level":"상","question":"Spring Data JPA의 @Modifying 벌크 쿼리 실행 후 영속성 컨텍스트에서 어떤 문제가 생기고 어떻게 해결하나요?","answer":"벌크 update/delete JPQL은 DB에 직접 실행되고 영속성 컨텍스트와 동기화되지 않아, 이미 로딩된 엔티티가 변경 전 값을 계속 보여줍니다. @Modifying(clearAutomatically = true)로 실행 후 EntityManager를 비운 뒤 다시 조회하면 됩니다. 벌크 연산은 더티 체킹을 거치지 않으며, 명세상 @Version 값도 쿼리에서 직접 갱신하지 않으면 증가하지 않습니다.","keywords":["@Modifying","벌크","clearAutomatically","영속성 컨텍스트"],"source":"https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html","followups":["clearAutomatically 없이 벌크 UPDATE 후 조회하면 어떤 값이 나오나요?","벌크 쿼리는 변경 감지·@Version과 어떤 관계가 있나요?"]},{"id":"sql-01","topic":"SQL","level":"하","question":"INNER JOIN과 LEFT JOIN의 차이를 설명해 주세요.","answer":"INNER JOIN은 ON 조건을 만족하는 행 쌍만 결과에 포함합니다. LEFT JOIN은 왼쪽 테이블의 모든 행을 유지하고, 오른쪽에 일치하는 행이 없으면 오른쪽 컬럼을 NULL로 채웁니다. 이 성질을 이용해 'LEFT JOIN 후 오른쪽 키 IS NULL'로 짝이 없는 행을 찾을 수 있습니다.","keywords":["INNER JOIN","LEFT JOIN","ON 조건","NULL"],"source":"https://dev.mysql.com/doc/refman/8.4/en/join.html","followups":["LEFT JOIN에서 오른쪽 테이블 조건을 WHERE에 쓰면 결과가 어떻게 달라지나요?","ON과 WHERE의 차이를 예로 설명해 보세요."]},{"id":"sql-02","topic":"SQL","level":"중","question":"FULL OUTER JOIN과 CROSS JOIN은 무엇이고, MySQL에서는 어떻게 다루나요?","answer":"FULL OUTER JOIN은 양쪽 테이블의 일치하지 않는 행까지 모두 포함하고, CROSS JOIN은 두 테이블의 모든 행 조합(곱집합)을 만듭니다. 방언 차이로 MySQL은 FULL OUTER JOIN 문법이 없어 LEFT JOIN과 RIGHT JOIN 결과를 UNION으로 합쳐 흉내 내고, SQLite는 3.39 이상에서 FULL JOIN을 지원합니다. 또 MySQL에서는 JOIN, CROSS JOIN, INNER JOIN이 문법상 서로 바꿔 쓸 수 있지만 표준 SQL에서는 다릅니다.","keywords":["FULL OUTER JOIN","CROSS JOIN","곱집합","UNION","방언"],"source":"https://dev.mysql.com/doc/refman/8.4/en/join.html","followups":["MySQL에서 FULL OUTER JOIN을 흉내 낼 때 UNION과 UNION ALL 중 무엇을 쓰나요?","CROSS JOIN을 의도적으로 쓰는 경우는 언제인가요?"]},{"id":"sql-03","topic":"SQL","level":"하","question":"PRIMARY KEY와 UNIQUE 제약의 차이는 무엇인가요?","answer":"둘 다 컬럼 값의 중복을 막지만, 테이블당 PRIMARY KEY는 하나만 둘 수 있고 UNIQUE는 여러 개 둘 수 있습니다. PRIMARY KEY 컬럼은 NULL을 가질 수 없습니다. InnoDB는 PRIMARY KEY를 클러스터드 인덱스로 사용합니다.","keywords":["PRIMARY KEY","UNIQUE","NULL","중복 방지"],"source":"https://dev.mysql.com/doc/refman/8.4/en/constraint-primary-key.html","followups":["UNIQUE 컬럼에 NULL을 여러 개 넣을 수 있나요?","한 테이블에 PRIMARY KEY와 UNIQUE를 각각 몇 개까지 둘 수 있나요?"]},{"id":"sql-04","topic":"SQL","level":"하","question":"DELETE, TRUNCATE, DROP의 차이를 설명해 주세요.","answer":"DELETE는 WHERE로 조건에 맞는 행을 지우는 DML이고, 트랜잭션 안에서 ROLLBACK할 수 있으며 ON DELETE 트리거가 동작합니다. TRUNCATE TABLE은 테이블의 모든 행을 비우고 AUTO_INCREMENT 값을 초기화하며, DML처럼 롤백할 수 없고 트리거도 실행되지 않습니다. DROP TABLE은 데이터뿐 아니라 테이블 정의 자체를 제거합니다. 방언 차이로 SQLite에는 TRUNCATE 문이 없어 조건 없는 DELETE로 대신합니다.","keywords":["DELETE","TRUNCATE","DROP","롤백","AUTO_INCREMENT"],"source":"https://dev.mysql.com/doc/refman/8.4/en/truncate-table.html","followups":["DELETE는 롤백되는데 TRUNCATE는 왜 안 되나요?","조건 없는 DELETE와 TRUNCATE 중 속도 차이는 왜 생기나요?"]},{"id":"sql-05","topic":"SQL","level":"하","question":"WHERE와 HAVING의 차이는 무엇인가요?","answer":"WHERE는 그룹으로 묶기 전에 개별 행을 걸러내고 집계 함수를 쓸 수 없습니다. HAVING은 GROUP BY로 그룹을 만든 뒤 그룹 단위 조건(예: COUNT(*) > 3)을 거릅니다. 행 단위로 걸러도 되는 조건은 WHERE에 두는 것이 처리할 행이 줄어 효율적입니다.","keywords":["WHERE","HAVING","GROUP BY","집계 함수"],"source":"https://dev.mysql.com/doc/refman/8.4/en/select.html","followups":["WHERE에서 집계 함수를 쓸 수 없는 이유는 무엇인가요?","조건을 WHERE로 옮길 수 있다면 HAVING보다 왜 유리한가요?"]},{"id":"sql-06","topic":"SQL","level":"하","question":"SELECT 문이 논리적으로 어떤 순서로 실행되는지 설명해 주세요.","answer":"논리적 처리 순서는 FROM(JOIN) → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT입니다. 그래서 SELECT에서 붙인 별칭을 WHERE에서 쓸 수 없고, ORDER BY에서는 쓸 수 있습니다. 이것은 개념적 순서이며 옵티마이저는 결과가 같은 범위에서 실제 실행 순서를 바꿀 수 있습니다. 방언 차이로 MySQL은 WHERE의 컬럼 별칭 참조를 허용하지 않지만 SQLite는 허용합니다.","keywords":["FROM","WHERE","GROUP BY","SELECT","ORDER BY"],"source":"https://dev.mysql.com/doc/refman/8.4/en/problems-with-alias.html","followups":["SELECT 별칭을 WHERE에서 쓸 수 없는 이유는 무엇인가요?","ORDER BY에서는 별칭을 쓸 수 있는 이유는 무엇인가요?"]},{"id":"sql-07","topic":"SQL","level":"하","question":"인덱스는 무엇이고 어떤 장단점이 있나요?","answer":"인덱스는 특정 컬럼 값으로 행을 빠르게 찾도록 별도로 유지하는 자료구조입니다. 인덱스가 없으면 조건에 맞는 행을 찾기 위해 테이블 전체를 읽어야 하지만, 인덱스가 있으면 해당 행 위치를 바로 찾을 수 있습니다. 대신 저장 공간을 쓰고 INSERT·UPDATE·DELETE 때 인덱스도 함께 갱신해야 하므로 쓰기 성능이 떨어집니다.","keywords":["인덱스","조회 성능","쓰기 비용","풀 스캔"],"source":"https://dev.mysql.com/doc/refman/8.4/en/mysql-indexes.html","followups":["인덱스를 컬럼마다 모두 만들면 어떤 문제가 생기나요?","카디널리티가 낮은 컬럼에 인덱스가 효과가 적은 이유는 무엇인가요?"]},{"id":"sql-08","topic":"SQL","level":"하","question":"SQL에서 NULL은 어떻게 비교하고, 집계 함수는 NULL을 어떻게 다루나요?","answer":"NULL은 '값이 없음·알 수 없음'이라서 = 나 <> 로 비교하면 참이 아니라 NULL이 되므로 IS NULL, IS NOT NULL을 써야 합니다. 대부분의 집계 함수는 NULL을 무시합니다. COUNT(*)는 NULL 여부와 상관없이 행 수를 세고, COUNT(컬럼)은 그 컬럼이 NULL이 아닌 행만 셉니다.","keywords":["NULL","IS NULL","COUNT(*)","COUNT(컬럼)"],"source":"https://dev.mysql.com/doc/refman/8.4/en/working-with-null.html","followups":["NULL = NULL의 결과는 무엇인가요?","NOT IN 서브쿼리 결과에 NULL이 있으면 어떻게 되나요?"]},{"id":"sql-09","topic":"SQL","level":"중","question":"B-Tree 인덱스는 왜 빠르고, 해시 인덱스와는 무엇이 다른가요?","answer":"MySQL의 대부분 인덱스(PRIMARY KEY, UNIQUE, INDEX)는 B-Tree로 저장되어 정렬된 상태로 탐색하므로 =, 비교 연산, BETWEEN 같은 범위 조건과 LIKE 'abc%' 같은 접두어 검색에 쓰일 수 있습니다. 해시 인덱스(MEMORY 엔진)는 = 와 <=> 동등 비교에만 매우 빠르고 범위 검색에는 쓸 수 없습니다. InnoDB는 일반 인덱스로 B-Tree를 사용합니다.","keywords":["B-Tree","범위 검색","해시 인덱스","동등 비교"],"source":"https://dev.mysql.com/doc/refman/8.4/en/index-btree-hash.html","followups":["범위 검색에 해시 인덱스를 쓰기 어려운 이유는 무엇인가요?","B-Tree의 높이가 성능에 어떤 영향을 주나요?"]},{"id":"sql-10","topic":"SQL","level":"상","question":"InnoDB의 클러스터드 인덱스와 보조(세컨더리) 인덱스는 어떻게 다른가요?","answer":"InnoDB는 테이블마다 행 데이터를 담는 클러스터드 인덱스를 가지며, 보통 PRIMARY KEY가 그 역할을 합니다. PRIMARY KEY가 없으면 NOT NULL인 첫 UNIQUE 인덱스를, 그것도 없으면 숨겨진 행 ID 기반 인덱스를 클러스터드 인덱스로 씁니다. 보조 인덱스를 탐색하면 인덱스에 저장된 기본키 값으로 클러스터드 인덱스를 한 번 더 조회하므로, 기본키가 길면 보조 인덱스도 커집니다.","keywords":["클러스터드 인덱스","보조 인덱스","PRIMARY KEY","InnoDB"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-index-types.html","followups":["보조 인덱스 조회 시 PK를 다시 조회하는 이유는 무엇인가요?","PK가 길면 보조 인덱스에 어떤 영향이 있나요?"]},{"id":"sql-11","topic":"SQL","level":"중","question":"복합 인덱스에서 컬럼 순서가 중요한 이유는 무엇인가요?","answer":"복합 인덱스는 왼쪽 컬럼부터 순서대로 정렬되어 있어 맨 앞 컬럼(leftmost prefix)을 조건에 쓰는 쿼리에 활용됩니다. 예를 들어 (last_name, first_name) 인덱스는 last_name 단독 조건이나 둘 다 쓴 조건에는 쓰이지만, first_name만 조건인 쿼리에는 쓰이지 않습니다. 그래서 자주 쓰는 동등 조건 컬럼을 앞에 두는 식으로 쿼리 패턴에 맞춰 순서를 정합니다.","keywords":["복합 인덱스","leftmost prefix","컬럼 순서"],"source":"https://dev.mysql.com/doc/refman/8.4/en/multiple-column-indexes.html","followups":["(a, b) 인덱스에서 b만 조건으로 걸면 인덱스를 탈 수 있나요?","복합 인덱스 컬럼 순서를 정하는 기준을 말해 보세요."]},{"id":"sql-12","topic":"SQL","level":"중","question":"인덱스가 있는데도 사용되지 않는 경우에는 어떤 것이 있나요?","answer":"대표적으로 LIKE '%abc'처럼 패턴이 와일드카드로 시작하면 B-Tree 인덱스를 탐색 시작점으로 쓸 수 없습니다. 복합 인덱스의 맨 앞 컬럼을 빼고 조건을 걸거나, 조건의 인덱스 컬럼에 함수나 연산을 적용해도 인덱스를 못 타는 경우가 많습니다. 또 조건에 맞는 행 비율이 높으면 옵티마이저가 풀 스캔을 선택하기도 하므로 EXPLAIN으로 실제 사용 여부를 확인합니다.","keywords":["LIKE 와일드카드","함수 적용","풀 스캔","EXPLAIN"],"source":"https://dev.mysql.com/doc/refman/8.4/en/index-btree-hash.html","followups":["인덱스 컬럼에 함수를 씌우면 왜 못 쓰나요? 어떻게 개선하나요?","컬럼과 값의 타입이 다르면 어떤 문제가 생기나요?"]},{"id":"sql-13","topic":"SQL","level":"중","question":"커버링 인덱스란 무엇인가요?","answer":"쿼리에 필요한 모든 컬럼이 인덱스에 들어 있어 테이블 본문을 읽지 않고 인덱스만으로 결과를 만드는 것을 커버링 인덱스(index-only scan)라고 합니다. MySQL의 EXPLAIN에서는 Extra 컬럼에 Using index로 표시됩니다. 테이블 행을 추가로 조회하지 않아 보통 풀 스캔보다 빠릅니다.","keywords":["커버링 인덱스","Using index","EXPLAIN"],"source":"https://dev.mysql.com/doc/refman/8.4/en/explain-output.html","followups":["커버링 인덱스가 되면 EXPLAIN의 Extra에 무엇이 나오나요?","SELECT *를 쓰면 커버링 인덱스가 어려운 이유는 무엇인가요?"]},{"id":"sql-14","topic":"SQL","level":"중","question":"EXPLAIN 결과에서 무엇을 보고 쿼리 성능 문제를 판단하나요?","answer":"type 컬럼으로 접근 방식을 보며 ALL이면 풀 테이블 스캔입니다. possible_keys와 key로 쓸 수 있는 인덱스와 실제 선택된 인덱스를, rows로 검사할 행 수의 추정치를 확인합니다. Extra에 Using filesort나 Using temporary가 보이면 정렬·임시 테이블 비용이 있다는 신호입니다. rows는 추정치이므로 실제 실행 시간과 함께 판단합니다.","keywords":["EXPLAIN","type","key","rows","Using filesort"],"source":"https://dev.mysql.com/doc/refman/8.4/en/explain-output.html","followups":["type이 ALL이면 무엇을 의미하고 어떻게 개선하나요?","Using filesort가 보이면 반드시 문제인가요?"]},{"id":"sql-15","topic":"SQL","level":"하","question":"정규화란 무엇이고 1NF, 2NF, 3NF는 각각 무엇을 해결하나요?","answer":"정규화는 데이터 중복과 갱신·삽입·삭제 이상을 줄이도록 테이블을 분리하는 설계 과정입니다. 1NF는 각 컬럼이 더 쪼갤 수 없는 단일 값을 갖게 하고, 2NF는 기본키 일부에만 종속된 컬럼(부분 종속)을 분리하며, 3NF는 기본키가 아닌 컬럼을 통해 다른 컬럼이 결정되는 이행 종속을 분리합니다. 분리한 테이블은 외래 키로 연결해 참조 무결성을 지킵니다.","keywords":["정규화","이상 현상","부분 종속","이행 종속","외래 키"],"source":"https://dev.mysql.com/doc/refman/8.4/en/create-table-foreign-keys.html","followups":["정규화를 과하게 하면 어떤 단점이 있나요?","성능을 위해 일부러 반정규화하는 경우를 예로 들어 보세요."]},{"id":"sql-16","topic":"SQL","level":"중","question":"트랜잭션의 ACID는 무엇인가요?","answer":"원자성(Atomicity)은 트랜잭션의 작업이 모두 반영되거나 모두 취소되는 것이고, 일관성(Consistency)은 제약 조건을 지키며 유효한 상태에서 다른 유효한 상태로 바뀌는 것입니다. 격리성(Isolation)은 동시에 실행되는 트랜잭션이 서로 영향을 주지 않도록 하는 것이고, 지속성(Durability)은 커밋된 결과가 장애 후에도 유지되는 것입니다. MySQL에서는 InnoDB 엔진이 COMMIT·ROLLBACK, 격리 수준 등으로 이를 제공합니다.","keywords":["Atomicity","Consistency","Isolation","Durability","InnoDB"],"source":"https://dev.mysql.com/doc/refman/8.4/en/mysql-acid.html","followups":["Durability는 InnoDB에서 어떤 로그로 보장되나요?","Atomicity는 어떻게 구현되나요?"]},{"id":"sql-17","topic":"SQL","level":"중","question":"트랜잭션 격리 수준 4가지와 각각 막아 주는 이상 현상을 설명해 주세요.","answer":"SQL 표준의 격리 수준은 READ UNCOMMITTED, READ COMMITTED, REPEATABLE READ, SERIALIZABLE이며 아래로 갈수록 격리가 강해지고 동시성은 낮아집니다. READ UNCOMMITTED는 커밋 전 데이터를 읽는 dirty read가 가능하고, READ COMMITTED는 이를 막지만 같은 쿼리의 결과가 바뀌는 non-repeatable read가 가능하며, REPEATABLE READ는 이를 막습니다. SERIALIZABLE은 가장 엄격합니다. InnoDB의 기본값은 REPEATABLE READ이고, 방언 차이로 SQLite는 기본적으로 모든 트랜잭션이 serializable입니다.","keywords":["READ COMMITTED","REPEATABLE READ","dirty read","non-repeatable read","SERIALIZABLE"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html","followups":["MySQL InnoDB의 기본 격리 수준은 무엇인가요?","non-repeatable read와 phantom read의 차이를 예로 설명해 보세요."]},{"id":"sql-18","topic":"SQL","level":"중","question":"InnoDB는 MVCC(일관된 읽기)로 어떻게 잠금 없이 읽기를 처리하나요?","answer":"InnoDB는 다중 버전(multi-versioning)으로 특정 시점의 스냅샷을 만들어 일반 SELECT(consistent nonlocking read)에 보여 주므로 읽기가 쓰기를 기다리지 않습니다. REPEATABLE READ에서는 트랜잭션 안의 일관된 읽기가 첫 읽기 때 만들어진 같은 스냅샷을 읽고, READ COMMITTED에서는 읽을 때마다 새 스냅샷을 만듭니다. 스냅샷이 아니라 최신 데이터를 잠그며 읽으려면 SELECT ... FOR UPDATE 같은 locking read를 씁니다.","keywords":["MVCC","스냅샷","consistent read","REPEATABLE READ"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-consistent-read.html","followups":["MVCC에서 undo log는 어떤 역할을 하나요?","일관된 읽기에서도 최신 값을 읽어야 한다면 어떻게 하나요?"]},{"id":"sql-19","topic":"SQL","level":"상","question":"갭 락과 넥스트 키 락은 무엇이고 왜 필요한가요?","answer":"레코드 락은 인덱스 레코드 자체를 잠그고, 갭 락은 인덱스 레코드 사이의 빈 구간을 잠가 그 범위에 다른 트랜잭션이 값을 INSERT하지 못하게 합니다. 넥스트 키 락은 인덱스 레코드의 레코드 락과 그 앞 갭의 갭 락을 합친 것입니다. InnoDB는 이런 잠금으로 같은 범위 조회에 새 행이 나타나는 phantom row를 막으며, READ COMMITTED에서는 갭 락이 대부분 비활성화됩니다.","keywords":["갭 락","넥스트 키 락","레코드 락","phantom"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-locking.html","followups":["갭 락은 어떤 격리 수준에서 동작하나요?","갭 락 때문에 INSERT가 대기하는 상황을 예로 들어 보세요."]},{"id":"sql-20","topic":"SQL","level":"상","question":"데드락은 왜 발생하고 어떻게 줄이거나 대응하나요?","answer":"둘 이상의 트랜잭션이 서로 상대가 가진 잠금을 기다리며 순환 대기에 빠질 때 발생합니다. InnoDB는 기본적으로 데드락을 감지해 한 트랜잭션(희생자)을 롤백하므로 애플리케이션은 롤백된 트랜잭션을 재시도하도록 만들어야 합니다. 예방하려면 여러 테이블·행을 갱신할 때 모든 트랜잭션이 같은 순서로 접근하고, 트랜잭션을 짧게 유지하며, 조건 컬럼에 인덱스를 둬 잠그는 범위를 줄입니다.","keywords":["데드락","순환 대기","롤백 후 재시도","같은 순서","짧은 트랜잭션"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlocks.html","followups":["데드락이 발생했을 때 InnoDB는 어떻게 처리하나요?","애플리케이션에서 데드락 재시도를 구현할 때 주의점은 무엇인가요?"]},{"id":"sql-21","topic":"SQL","level":"중","question":"GROUP BY 사용 시 SELECT 목록에 집계되지 않은 컬럼을 쓰면 어떻게 되나요?","answer":"GROUP BY는 같은 값을 가진 행을 묶어 COUNT, SUM 같은 집계 함수를 그룹별로 계산합니다. MySQL은 ONLY_FULL_GROUP_BY SQL 모드가 기본으로 켜져 있어, GROUP BY에 없고 함수적 종속도 아닌 비집계 컬럼을 SELECT, HAVING, ORDER BY에서 쓰면 쿼리를 거부합니다. 방언 차이로 이 모드를 끄면 MySQL은 그룹 내 임의 값을 반환하므로 결과를 믿기 어렵습니다.","keywords":["GROUP BY","집계 함수","ONLY_FULL_GROUP_BY","함수적 종속"],"source":"https://dev.mysql.com/doc/refman/8.4/en/group-by-handling.html","followups":["ONLY_FULL_GROUP_BY가 꺼져 있으면 어떤 값이 나오나요?","함수적 종속이면 허용되는 이유는 무엇인가요?"]},{"id":"sql-22","topic":"SQL","level":"중","question":"COUNT(*), COUNT(컬럼), COUNT(DISTINCT 컬럼)의 차이는 무엇인가요?","answer":"COUNT(*)는 NULL 여부와 관계없이 조회된 행 수를 셉니다. COUNT(컬럼)은 그 컬럼이 NULL이 아닌 행만 세고, COUNT(DISTINCT 컬럼)은 NULL이 아닌 서로 다른 값의 개수를 셉니다. InnoDB는 동시 트랜잭션마다 보이는 행 수가 달라질 수 있어 테이블의 행 수를 따로 저장하지 않으므로 큰 테이블의 COUNT(*)는 느릴 수 있습니다.","keywords":["COUNT(*)","COUNT(컬럼)","DISTINCT","NULL"],"source":"https://dev.mysql.com/doc/refman/8.4/en/aggregate-functions.html","followups":["컬럼에 NULL이 있을 때 세 COUNT의 결과가 각각 어떻게 다른가요?","COUNT(DISTINCT ...)가 느린 이유는 무엇인가요?"]},{"id":"sql-23","topic":"SQL","level":"중","question":"서브쿼리와 JOIN은 어떻게 다르고 어떤 기준으로 선택하나요?","answer":"서브쿼리는 쿼리 안에 중첩된 SELECT로, 스칼라 값 비교, IN, EXISTS, 파생 테이블(FROM 절 서브쿼리) 등으로 쓰입니다. JOIN은 여러 테이블의 컬럼을 한 결과 행으로 합칠 때 적합하고, 서브쿼리는 다른 테이블의 컬럼이 결과에 필요 없고 존재 여부나 집계값 조건만 필요할 때 읽기 쉽습니다. 많은 경우 둘은 서로 바꿔 쓸 수 있고 성능은 옵티마이저와 데이터에 따라 달라지므로 EXPLAIN으로 비교합니다.","keywords":["서브쿼리","JOIN","파생 테이블","EXPLAIN"],"source":"https://dev.mysql.com/doc/refman/8.4/en/subqueries.html","followups":["서브쿼리를 JOIN으로 바꾸면 중복 행이 생길 수 있나요?","파생 테이블은 언제 쓰나요?"]},{"id":"sql-24","topic":"SQL","level":"상","question":"IN과 EXISTS, 그리고 상관 서브쿼리는 어떻게 다르게 동작하나요?","answer":"IN은 서브쿼리가 돌려준 값 집합에 포함되는지 비교하고, EXISTS는 서브쿼리가 행을 하나라도 돌려주는지만 확인하므로 서브쿼리 SELECT 목록의 값은 중요하지 않습니다. 상관 서브쿼리는 바깥 쿼리의 컬럼을 참조하므로 개념적으로 바깥 행마다 평가됩니다. MySQL 옵티마이저는 IN·EXISTS 서브쿼리를 semijoin 등으로 변환해 최적화하므로 성능 차이는 버전과 데이터에 따라 달라지며 EXPLAIN으로 확인해야 합니다.","keywords":["IN","EXISTS","상관 서브쿼리","semijoin"],"source":"https://dev.mysql.com/doc/refman/8.4/en/semijoins.html","followups":["EXISTS는 왜 일치하는 행을 하나 찾으면 멈추나요?","NOT IN과 NOT EXISTS는 NULL에서 결과가 어떻게 다른가요?"]},{"id":"sql-25","topic":"SQL","level":"상","question":"SELECT ... FOR UPDATE는 언제 쓰고 어떤 효과가 있나요?","answer":"조회한 행을 수정하려는 트랜잭션이 그 사이 다른 트랜잭션에 값을 바뀌지 않게 하려고 행에 배타 잠금(X lock)을 거는 locking read입니다. 다른 트랜잭션은 해당 행을 UPDATE하거나 FOR SHARE로 읽을 수 없고 트랜잭션이 끝날 때까지 기다립니다. 재고 차감처럼 읽고 나서 쓰는 로직에서 갱신 손실을 막는 데 쓰지만, 잠금 대기와 데드락 위험이 있고 조건 컬럼에 인덱스가 없으면 더 많은 행이 잠길 수 있습니다.","keywords":["FOR UPDATE","배타 잠금","locking read","갱신 손실"],"source":"https://dev.mysql.com/doc/refman/8.4/en/innodb-locking-reads.html","followups":["FOR UPDATE의 락은 언제 해제되나요?","FOR UPDATE를 인덱스 없는 조건에 쓰면 어떤 문제가 생기나요?"]},{"id":"sql-26","topic":"SQL","level":"중","question":"LIMIT/OFFSET 페이징은 어떻게 동작하고 어떤 한계가 있나요?","answer":"LIMIT은 반환 행 수를, OFFSET은 앞에서 건너뛸 행 수를 지정합니다. ORDER BY가 없으면 순서가 보장되지 않아 페이지마다 결과가 달라질 수 있으니 유일한 정렬 기준을 함께 써야 합니다. OFFSET으로 건너뛴 행도 서버 안에서는 계산해야 하므로 OFFSET이 커질수록 비효율적일 수 있습니다. MySQL에서는 `LIMIT 개수 OFFSET 건너뛸수` 또는 `LIMIT 건너뛸수, 개수` 형태로 씁니다.","keywords":["LIMIT","OFFSET","ORDER BY","큰 OFFSET 비효율"],"followups":["페이지가 깊어져도 빠르게 하려면 어떤 방식을 고려할 수 있나요?","정렬 기준 값이 중복이면 페이지 경계에서 어떤 문제가 생기나요?"],"source":"https://www.postgresql.org/docs/current/queries-limit.html"},{"id":"cs-01","topic":"CS","level":"하","question":"프로세스와 스레드의 차이를 설명해 보세요.","answer":"프로세스는 실행 중인 프로그램에 운영체제가 독립된 주소 공간과 자원을 할당한 단위이고, 스레드는 한 프로세스 안에서 코드·데이터·힙을 공유하며 스택은 따로 갖는 실행 흐름입니다. 스레드끼리는 메모리를 공유해 통신이 쉽고 생성 비용이 작지만, 동기화를 잘못하면 경쟁 상태가 생기고 한 스레드의 치명적 오류가 프로세스 전체에 영향을 줍니다. 프로세스는 격리가 강해 안전한 대신 생성과 프로세스 간 통신 비용이 큽니다.","keywords":["독립된 주소 공간","힙 공유","스레드별 스택","경쟁 상태"],"followups":["멀티 프로세스 대신 멀티 스레드를 쓰는 이유는 무엇인가요?","Java 스레드에서 서로 공유되는 메모리 영역과 공유되지 않는 영역은 어디인가요?"],"source":"https://man7.org/linux/man-pages/man7/pthreads.7.html"},{"id":"cs-02","topic":"CS","level":"중","question":"컨텍스트 스위칭(문맥 교환)이란 무엇이고, 왜 비용이 드나요?","answer":"컨텍스트 스위칭은 CPU가 실행하던 프로세스·스레드를 멈추고 다른 것으로 바꿀 때 현재 레지스터 등 실행 상태를 저장하고 다음 대상의 상태를 복원하는 작업입니다. 저장·복원 자체와 스케줄러 실행 시간이 들고, 프로세스가 바뀌면 주소 공간이 달라져 캐시와 TLB의 효율이 떨어지는 간접 비용도 큽니다. 그래서 선점이 너무 잦거나 스레드를 지나치게 많이 만들면 오히려 처리량이 떨어질 수 있습니다.","keywords":["상태 저장·복원","스케줄러","캐시·TLB","선점"],"followups":["프로세스 간 전환과 같은 프로세스 안 스레드 간 전환의 비용은 왜 다른가요?","스레드 풀을 쓰면 컨텍스트 스위칭 관점에서 어떤 이점이 있나요?"],"source":"https://man7.org/linux/man-pages/man7/sched.7.html"},{"id":"cs-03","topic":"CS","level":"상","question":"데드락이 발생하는 조건과 예방 방법을 설명해 보세요.","answer":"데드락은 둘 이상의 스레드가 서로 상대가 쥔 락을 기다리며 영원히 멈추는 상태이고, 보통 상호 배제·점유 대기·비선점·순환 대기 네 조건이 모두 성립할 때 생깁니다. 이 중 하나만 깨면 예방할 수 있어서, 모든 스레드가 락을 같은 순서로 얻게 하거나 락 대기에 타임아웃을 두고 실패하면 가진 락을 풀고 재시도합니다. 락 범위를 줄이고 한 번에 여러 락을 잡지 않는 설계도 도움이 됩니다.","keywords":["상호 배제","점유 대기","비선점","순환 대기","락 순서"],"followups":["데드락, 라이브락, 기아 상태는 각각 어떻게 다른가요?","Java에서 데드락이 의심될 때 어떻게 확인하나요?"],"source":"https://docs.oracle.com/javase/tutorial/essential/concurrency/deadlock.html"},{"id":"cs-04","topic":"CS","level":"중","question":"뮤텍스와 세마포어의 차이는 무엇인가요?","answer":"뮤텍스는 임계 구역에 한 번에 한 스레드만 들어가게 하는 락이고, 보통 락을 건 스레드가 직접 해제하는 소유권 개념이 있습니다. 세마포어는 0 아래로 내려가지 않는 정수 카운터로, 값이 0이면 대기하고 증가·감소 연산으로 동시에 접근할 수 있는 개수를 N개로 제한할 수 있으며 다른 스레드가 증가시켜 깨울 수도 있습니다. 그래서 상호 배제에는 뮤텍스, 자원 개수 제한이나 신호 전달에는 세마포어가 어울립니다.","keywords":["상호 배제","소유권","카운터","자원 개수 제한"],"followups":["이진 세마포어와 뮤텍스는 같다고 봐도 되나요?","Java에서 세마포어에 해당하는 클래스는 무엇인가요?"],"source":"https://man7.org/linux/man-pages/man7/sem_overview.7.html"},{"id":"cs-05","topic":"CS","level":"상","question":"가상 메모리와 페이징이 무엇이고 왜 쓰는지 설명해 보세요.","answer":"가상 메모리는 각 프로세스에 물리 메모리와 분리된 연속적인 주소 공간을 보여 주는 기법으로, 운영체제가 고정 크기 페이지 단위로 가상 주소를 물리 주소에 페이지 테이블로 매핑합니다. 덕분에 프로세스끼리 메모리가 격리되고, 물리 메모리보다 큰 공간을 쓸 수 있으며 자주 쓰지 않는 페이지는 디스크로 내보낼 수 있습니다. 주소 변환은 TLB가 최근 매핑을 캐시해 빠르게 하고, 필요한 페이지가 메모리에 없으면 페이지 폴트로 읽어 옵니다.","keywords":["페이지 테이블","TLB","프로세스 격리","페이지 폴트","스왑"],"followups":["페이지 폴트가 났을 때 운영체제는 어떤 일을 하나요?","스래싱은 무엇이고 어떻게 줄이나요?"],"source":"https://docs.kernel.org/admin-guide/mm/concepts.html"},{"id":"cs-06","topic":"CS","level":"중","question":"사용자 모드와 커널 모드, 그리고 시스템 콜은 무엇인가요?","answer":"운영체제는 보호를 위해 일반 프로그램은 제한된 사용자 모드에서, 하드웨어와 자원 관리 코드는 특권을 가진 커널 모드에서 실행되도록 나눕니다. 시스템 콜은 사용자 프로그램이 파일 읽기, 프로세스 생성, 메모리 할당 같은 커널 기능이 필요할 때 쓰는 공식 인터페이스이고, 호출하면 커널 모드로 전환된 뒤 결과를 받아 돌아옵니다. 이 전환에 비용이 들기 때문에 시스템 콜을 줄이려고 버퍼링을 사용합니다.","keywords":["사용자 모드","커널 모드","시스템 콜","모드 전환"],"followups":["read() 같은 시스템 콜을 Java 코드에서 호출하면 어떤 경로를 거치나요?","버퍼 입출력이 시스템 콜 횟수를 줄이는 원리는 무엇인가요?"],"source":"https://man7.org/linux/man-pages/man2/syscalls.2.html"},{"id":"cs-07","topic":"CS","level":"중","question":"CPU 스케줄링에서 선점형과 비선점형, 대표 알고리즘을 설명해 보세요.","answer":"비선점형은 실행 중인 작업이 스스로 끝나거나 대기할 때까지 CPU를 뺏지 않고, 선점형은 더 높은 우선순위 작업이 오거나 시간 할당량이 끝나면 운영체제가 CPU를 회수합니다. 라운드 로빈은 작업마다 같은 시간 할당량을 돌아가며 주는 방식으로 응답성이 좋고, 우선순위 스케줄링은 중요한 작업을 먼저 실행하지만 낮은 우선순위가 계속 밀리는 기아가 생길 수 있어 에이징으로 보완합니다. 범용 OS는 보통 선점형을 씁니다.","keywords":["선점형","라운드 로빈","우선순위","시간 할당량","기아"],"followups":["타임 슬라이스를 너무 짧게 또는 길게 잡으면 어떤 문제가 생기나요?","FIFO 스케줄링과 라운드 로빈의 평균 대기 시간은 어떻게 다른가요?"],"source":"https://man7.org/linux/man-pages/man7/sched.7.html"},{"id":"cs-08","topic":"CS","level":"하","question":"HTTP의 GET과 POST 차이, 그리고 멱등성이란 무엇인가요?","answer":"GET은 리소스를 조회하는 안전한 메서드로 서버 상태를 바꾸지 않고, 요청 정보는 주로 URL 쿼리로 보내며 캐시와 북마크가 가능합니다. POST는 본문에 데이터를 담아 리소스를 만들거나 처리를 요청하는 용도라 같은 요청을 반복하면 결과가 달라질 수 있습니다. 멱등성은 같은 요청을 여러 번 보내도 서버 상태가 한 번 보낸 것과 같다는 성질로, GET·PUT·DELETE는 멱등이고 POST와 PATCH는 보장되지 않습니다.","keywords":["안전한 메서드","멱등성","PUT","POST","캐시"],"followups":["결제 요청처럼 POST가 중복 전송되는 문제는 어떻게 막나요?","PUT과 PATCH의 차이는 무엇인가요?"],"source":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Methods"},{"id":"cs-09","topic":"CS","level":"하","question":"HTTP 상태 코드를 분류하고 자주 쓰는 코드의 의미를 설명해 보세요.","answer":"2xx는 성공(200 OK, 201 Created), 3xx는 리다이렉션(301 영구 이동, 304 캐시 사용), 4xx는 클라이언트 오류, 5xx는 서버 오류입니다. 4xx에서 401은 인증이 필요하거나 실패한 경우, 403은 인증됐지만 권한이 없는 경우, 404는 리소스를 찾을 수 없는 경우입니다. 5xx에서 500은 서버 내부 오류, 502는 게이트웨이가 상위 서버에서 잘못된 응답을 받은 경우, 503은 서버가 과부하·점검으로 요청을 처리할 수 없는 경우입니다.","keywords":["2xx 성공","3xx 리다이렉션","401과 403","5xx 서버 오류"],"followups":["REST API에서 입력값 검증 실패는 400과 422 중 무엇으로 응답하나요?","301과 302의 차이는 무엇인가요?"],"source":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status"},{"id":"cs-10","topic":"CS","level":"중","question":"TCP의 3-way handshake와 4-way handshake를 설명해 보세요.","answer":"3-way handshake는 클라이언트가 SYN, 서버가 SYN+ACK, 클라이언트가 ACK를 보내며 양쪽이 초기 시퀀스 번호를 교환해 연결을 확립하는 과정입니다. 연결 종료는 각 방향을 따로 닫기 때문에 한쪽이 FIN을 보내고 상대가 ACK로 답한 뒤, 상대도 자기 FIN을 보내고 ACK를 받는 4단계가 기본입니다. 먼저 닫은 쪽은 마지막 ACK가 유실되거나 늦은 패킷이 올 때를 대비해 TIME-WAIT 상태로 잠시 기다립니다.","keywords":["SYN","ACK","초기 시퀀스 번호","FIN","TIME-WAIT"],"followups":["왜 2-way가 아니라 3-way인가요?","TIME-WAIT 소켓이 많이 쌓이면 어떤 문제가 생기나요?"],"source":"https://www.rfc-editor.org/rfc/rfc9293.html"},{"id":"cs-11","topic":"CS","level":"하","question":"TCP와 UDP의 차이는 무엇인가요?","answer":"TCP는 연결을 먼저 맺고 순서 보장, 재전송, 흐름 제어, 혼잡 제어로 신뢰성 있는 바이트 스트림을 제공합니다. UDP는 연결 없이 데이터그램을 보내고 도착·순서·중복 방지를 보장하지 않는 대신 헤더가 작고 지연이 적습니다. 그래서 웹, 파일 전송, 메일처럼 정확성이 중요하면 TCP, 실시간 음성·영상, 게임, DNS 조회처럼 속도가 중요하면 UDP를 씁니다.","keywords":["연결 지향","신뢰성","흐름·혼잡 제어","비연결","낮은 지연"],"followups":["UDP를 쓰면서 신뢰성이 필요하면 어떻게 하나요?","HTTP/3가 UDP 위에서 동작하는 이유는 무엇인가요?"],"source":"https://www.rfc-editor.org/rfc/rfc768.html"},{"id":"cs-12","topic":"CS","level":"상","question":"HTTPS는 어떻게 동작하나요? TLS 핸드셰이크 과정을 설명해 보세요.","answer":"HTTPS는 HTTP를 TLS로 감싸 도청, 변조, 위조를 막는 방식입니다. 핸드셰이크에서 클라이언트와 서버가 지원하는 암호 방식을 협상하고 Diffie-Hellman 계열 키 교환으로 같은 비밀 값을 만들며, 서버는 인증서와 서명으로 자신이 맞는 도메인의 서버임을 증명합니다. 이후 실제 데이터는 이렇게 만든 세션 키로 빠른 대칭 암호화를 해서 보냅니다. TLS 1.3은 핸드셰이크를 줄여 왕복 횟수를 줄였습니다.","keywords":["인증서","키 교환","대칭키 암호화","무결성","TLS 1.3"],"followups":["인증서를 누가 어떻게 신뢰하는지(인증서 체인) 설명해 보세요.","왜 데이터 전체를 비대칭키로 암호화하지 않나요?"],"source":"https://www.rfc-editor.org/rfc/rfc8446.html"},{"id":"cs-13","topic":"CS","level":"하","question":"DNS는 무엇이고, 도메인 이름을 IP로 바꾸는 과정을 설명해 보세요.","answer":"DNS는 사람이 읽는 도메인 이름을 IP 주소로 바꿔 주는 분산 계층형 이름 시스템입니다. 클라이언트는 먼저 로컬 캐시를 보고, 없으면 재귀 리졸버에 묻고, 리졸버는 루트 서버, TLD 서버, 해당 도메인의 권한 네임서버 순으로 물어 최종 IP를 받아 돌려줍니다. 응답은 TTL 동안 캐시되어 다음 조회가 빨라지지만, 레코드를 바꿔도 TTL이 지나야 반영된다는 점을 기억해야 합니다.","keywords":["도메인→IP","재귀 리졸버","루트·TLD·권한 서버","TTL 캐시"],"followups":["A 레코드와 CNAME 레코드의 차이는 무엇인가요?","DNS 변경이 전 세계에 바로 반영되지 않는 이유는 무엇인가요?"],"source":"https://www.rfc-editor.org/rfc/rfc1034.html"},{"id":"cs-14","topic":"CS","level":"하","question":"쿠키와 세션의 차이는 무엇인가요?","answer":"쿠키는 서버가 Set-Cookie 헤더로 내려 주면 브라우저가 저장하고 이후 같은 사이트 요청에 자동으로 보내는 작은 데이터입니다. 세션은 로그인 상태 같은 정보를 서버에 두고 브라우저에는 세션 ID만 쿠키로 들고 있게 하는 방식이라, 민감한 데이터가 클라이언트에 남지 않지만 서버가 상태를 관리해야 합니다. 쿠키에는 HttpOnly로 스크립트 접근 차단, Secure로 HTTPS 전송 한정, SameSite로 크로스 사이트 전송 제한 같은 보안 속성을 설정합니다.","keywords":["Set-Cookie","세션 ID","HttpOnly","Secure","SameSite"],"followups":["서버가 여러 대일 때 세션을 어떻게 공유하나요?","CSRF 공격은 무엇이고 SameSite가 어떻게 도움이 되나요?"],"source":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies"},{"id":"cs-15","topic":"CS","level":"중","question":"CORS는 무엇이고 왜 발생하며 어떻게 해결하나요?","answer":"브라우저는 동일 출처 정책으로 다른 출처(스킴·호스트·포트)의 응답을 스크립트가 마음대로 읽지 못하게 막고, CORS는 서버가 헤더로 이를 허용하는 표준 방식입니다. 서버가 Access-Control-Allow-Origin 등으로 허용할 출처·메서드·헤더를 응답하면 브라우저가 통과시키며, 일반적이지 않은 요청은 먼저 OPTIONS 프리플라이트 요청으로 허용 여부를 확인합니다. 따라서 해결은 서버(또는 프록시)에서 허용 출처를 설정하는 것이고, 프론트에서 우회할 수 있는 문제가 아닙니다.","keywords":["동일 출처 정책","Access-Control-Allow-Origin","프리플라이트","OPTIONS"],"followups":["Spring에서 CORS를 설정하는 방법을 아는 대로 말해 보세요.","자격 증명(쿠키)을 포함한 요청에서 허용 출처를 *로 둘 수 없는 이유는 무엇인가요?"],"source":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS"},{"id":"cs-16","topic":"CS","level":"중","question":"HTTP 캐시는 어떻게 동작하나요? Cache-Control과 ETag를 설명해 보세요.","answer":"캐시는 응답을 저장해 두었다가 재사용해 지연과 서버 부하를 줄입니다. Cache-Control: max-age는 지정한 시간 동안 서버에 묻지 않고 캐시를 쓰게 하고, no-store는 저장 자체를 금지하며, no-cache는 저장은 하되 쓸 때마다 서버에 유효성 검증을 요구합니다. 검증에는 ETag를 If-None-Match로 보내고 서버가 변경이 없으면 본문 없이 304 Not Modified로 응답해 전송량을 아낍니다.","keywords":["max-age","no-store와 no-cache","ETag","304 Not Modified"],"followups":["정적 파일을 오래 캐시하면서도 배포 시 바로 갱신하려면 어떻게 하나요?","no-cache와 no-store를 헷갈리면 어떤 문제가 생기나요?"],"source":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching"},{"id":"cs-17","topic":"CS","level":"중","question":"브라우저 주소창에 URL을 입력하고 엔터를 치면 어떤 일이 일어나나요?","answer":"브라우저는 먼저 DNS로 도메인의 IP 주소를 찾고, 그 서버와 TCP 연결을 맺으며 HTTPS라면 TLS 핸드셰이크를 추가로 합니다. 그다음 HTTP 요청을 보내 서버가 HTML을 응답하면, 브라우저가 HTML을 파싱하면서 CSS·JS·이미지를 추가로 요청하고 렌더링해 화면을 그립니다. 중간에 캐시, 리다이렉트, CDN, 로드 밸런서가 끼어들 수 있어서 어느 단계에서 느려졌는지 나눠서 보는 것이 중요합니다.","keywords":["DNS 조회","TCP/TLS 연결","HTTP 요청·응답","HTML 파싱·렌더링"],"followups":["각 단계에서 지연이 생기면 어떻게 원인을 찾나요?","CDN은 이 흐름의 어느 부분을 줄여 주나요?"],"source":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Web_standards/How_the_web_works"},{"id":"cs-18","topic":"CS","level":"상","question":"HTTP/1.1과 HTTP/2의 차이는 무엇인가요?","answer":"HTTP/1.1은 텍스트 기반이고 한 연결에서 요청과 응답이 순서대로 처리되어 앞 응답이 느리면 뒤가 기다리는 문제가 있어 브라우저가 연결을 여러 개 엽니다. HTTP/2는 바이너리 프레임으로 나눈 여러 스트림을 한 TCP 연결에서 동시에 주고받는 멀티플렉싱과 HPACK 헤더 압축을 제공해 연결 수와 헤더 낭비를 줄입니다. 다만 전송이 TCP 위라서 패킷이 유실되면 연결 전체가 지연되는 한계가 남고, 이를 UDP 기반 QUIC을 쓰는 HTTP/3가 개선합니다.","keywords":["멀티플렉싱","바이너리 프레임","HPACK","HOL 블로킹"],"followups":["HTTP/1.1 시절의 도메인 샤딩이나 스프라이트 같은 기법이 HTTP/2에서는 왜 덜 필요한가요?","HTTP/3는 HOL 블로킹을 어떻게 완화하나요?"],"source":"https://www.rfc-editor.org/rfc/rfc9113.html"},{"id":"cs-19","topic":"CS","level":"하","question":"OSI 7계층과 TCP/IP 4계층을 비교해 설명해 보세요.","answer":"OSI는 물리·데이터 링크·네트워크·전송·세션·표현·응용의 7계층 참조 모델이고, 실제 인터넷 프로토콜은 링크·인터넷·전송·응용의 4계층 TCP/IP 모델로 설명합니다. 인터넷 계층은 IP로 주소 지정과 라우팅을, 전송 계층은 TCP·UDP로 프로세스 간 통신을, 응용 계층은 HTTP·DNS 같은 프로토콜을 맡습니다. 각 계층은 아래 계층의 기능만 이용하고 헤더를 덧붙이는 캡슐화로 독립적으로 발전할 수 있습니다.","keywords":["7계층 vs 4계층","IP 라우팅","전송 계층","캡슐화"],"followups":["L4 로드 밸런서와 L7 로드 밸런서는 어떻게 다른가요?","HTTP 요청이 각 계층에서 어떻게 캡슐화되는지 설명해 보세요."],"source":"https://www.rfc-editor.org/rfc/rfc1122.html"},{"id":"cs-20","topic":"CS","level":"상","question":"JWT는 무엇이고 세션 방식과 비교해 장단점은 무엇인가요?","answer":"JWT는 헤더, 페이로드(클레임), 서명 세 부분을 점으로 이어 붙인 토큰으로, 서버는 서명만 검증하면 DB 조회 없이 사용자 정보를 신뢰할 수 있어 여러 서버에 확장하기 쉽습니다. 단점은 페이로드가 암호화가 아니라 인코딩이라 민감 정보를 넣으면 안 되고, 이미 발급한 토큰을 만료 전에 무효화하기 어렵다는 점입니다. 그래서 액세스 토큰은 만료를 짧게 하고 리프레시 토큰과 저장 위치 보안, 필요하면 블랙리스트를 함께 설계합니다.","keywords":["헤더·페이로드·서명","서명 검증","무상태","토큰 무효화","만료"],"followups":["JWT를 localStorage와 HttpOnly 쿠키 중 어디에 저장하는 것이 낫고 왜 그런가요?","서명 알고리즘 HS256과 RS256의 차이는 무엇인가요?"],"source":"https://www.rfc-editor.org/rfc/rfc7519.html"},{"id":"cs-21","topic":"CS","level":"하","question":"배열(ArrayList)과 연결 리스트(LinkedList)의 차이와 선택 기준을 설명해 보세요.","answer":"배열 기반 리스트는 연속된 메모리에 저장해 인덱스 접근이 상수 시간이고 캐시 효율이 좋지만, 중간 삽입·삭제는 뒤 요소를 밀어야 해서 선형 시간입니다. 연결 리스트는 노드가 앞뒤 노드를 참조해 이미 위치를 알고 있는 노드의 삽입·삭제는 빠르지만, 인덱스로 접근하면 처음이나 끝에서부터 따라가야 해서 선형 시간이고 노드당 메모리가 더 듭니다. 실무에서는 대부분 조회가 많아 ArrayList를 기본으로 씁니다.","keywords":["인덱스 접근","중간 삽입·삭제","메모리 연속성","ArrayList 기본 선택"],"followups":["ArrayList의 용량이 가득 차면 내부에서 어떤 일이 일어나나요?","LinkedList가 실제로 ArrayList보다 빠른 경우가 드문 이유는 무엇인가요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/LinkedList.html"},{"id":"cs-22","topic":"CS","level":"하","question":"스택과 큐의 차이를 설명하고, 각각 어디에 쓰이는지 말해 보세요.","answer":"스택은 마지막에 넣은 것을 먼저 꺼내는 LIFO 구조로, 함수 호출 스택, 되돌리기(undo), 괄호 검사, DFS에 쓰입니다. 큐는 먼저 넣은 것을 먼저 꺼내는 FIFO 구조로, 작업 대기열, 메시지 큐, BFS에 쓰입니다. Java에서는 양쪽 끝에서 넣고 뺄 수 있는 Deque 인터페이스(ArrayDeque)를 스택과 큐 용도로 모두 쓰며, 레거시 Stack 클래스보다 Deque를 우선하라고 문서가 안내합니다.","keywords":["LIFO","FIFO","Deque","ArrayDeque"],"followups":["재귀 호출이 너무 깊어지면 어떤 오류가 나고 왜 그런가요?","큐 두 개로 스택을, 스택 두 개로 큐를 만들 수 있나요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/Deque.html"},{"id":"cs-23","topic":"CS","level":"중","question":"해시 테이블의 동작 원리와 해시 충돌 해결 방법을 설명해 보세요.","answer":"해시 테이블은 키에 해시 함수를 적용해 배열의 버킷 위치를 정하고 그곳에 값을 저장해, 평균적으로 상수 시간에 조회·삽입·삭제를 합니다. 서로 다른 키가 같은 버킷에 들어가는 충돌은 버킷에 연결 리스트(또는 트리)로 이어 붙이는 체이닝이나, 다른 빈 칸을 찾는 오픈 어드레싱으로 해결합니다. 항목이 늘어 적재율이 임계값을 넘으면 버킷 수를 늘려 다시 해싱하며, 해시 분포가 나쁘면 성능이 선형까지 떨어집니다.","keywords":["해시 함수","버킷","충돌 해결","적재율","리해시"],"followups":["키 객체의 hashCode와 equals를 함께 재정의해야 하는 이유는 무엇인가요?","HashMap의 기본 적재율과 용량 확장은 어떻게 동작하나요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/HashMap.html"},{"id":"cs-24","topic":"CS","level":"중","question":"이진 탐색 트리와 균형 트리(레드-블랙 트리)를 설명해 보세요.","answer":"이진 탐색 트리는 왼쪽 자식은 부모보다 작고 오른쪽은 큰 규칙으로, 탐색·삽입이 트리 높이에 비례하며 균형이면 O(log n)입니다. 정렬된 데이터를 차례로 넣으면 한쪽으로 치우쳐 높이가 n이 되어 O(n)까지 나빠집니다. 레드-블랙 트리 같은 자가 균형 트리는 삽입·삭제 때 회전과 색 규칙으로 높이를 로그로 유지하며, Java TreeMap이 이 구조로 키를 정렬해 보관합니다.","keywords":["이진 탐색 트리","높이와 시간복잡도","자가 균형","레드-블랙 트리","TreeMap"],"followups":["HashMap과 TreeMap은 어떤 경우에 각각 선택하나요?","트리를 중위 순회하면 어떤 순서로 방문하나요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/TreeMap.html"},{"id":"cs-25","topic":"CS","level":"중","question":"힙(Heap)과 우선순위 큐를 설명해 보세요.","answer":"힙은 부모가 자식보다 항상 작거나(최소 힙) 큰(최대 힙) 완전 이진 트리로, 보통 배열에 저장합니다. 우선순위 큐는 가장 우선순위가 높은 원소를 먼저 꺼내는 자료구조이고 힙으로 구현하면 삽입과 삭제가 O(log n), 최솟값 확인은 O(1)입니다. Java PriorityQueue는 기본이 자연 순서의 최소 힙이며 Comparator로 순서를 바꿀 수 있고, 반복자가 정렬된 순서를 보장하지 않는다는 점에 주의해야 합니다.","keywords":["완전 이진 트리","최소 힙","O(log n)","PriorityQueue","Comparator"],"followups":["힙 정렬의 시간복잡도와 특징은 무엇인가요?","상위 K개 원소를 구할 때 힙을 어떻게 쓰나요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/PriorityQueue.html"},{"id":"cs-26","topic":"CS","level":"하","question":"시간 복잡도와 Big-O 표기법을 설명해 보세요.","answer":"시간 복잡도는 입력 크기 n이 커질 때 연산 횟수가 어떻게 늘어나는지를 나타내며, Big-O는 그 증가율의 상한을 상수와 낮은 차수를 버리고 표기합니다. 상수 O(1), 로그 O(log n), 선형 O(n), O(n log n), 제곱 O(n²) 순으로 느려지며 같은 연산도 최선·평균·최악이 다를 수 있습니다. ArrayList의 add는 가끔 배열을 늘려 느리지만 평균하면 상수 시간이라는 상각 분석이 대표 사례입니다.","keywords":["입력 크기 n","O(1)·O(n)·O(n log n)","최악·평균","상각"],"followups":["O(n²) 알고리즘을 O(n log n)이나 O(n)으로 줄인 경험이나 예를 들어 보세요.","공간 복잡도와 시간 복잡도의 트레이드오프 예시를 들어 보세요."],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/ArrayList.html"},{"id":"cs-27","topic":"CS","level":"상","question":"대표적인 정렬 알고리즘의 시간복잡도와 안정 정렬이 무엇인지 설명하고, Java의 정렬은 어떤 알고리즘인가요?","answer":"버블·삽입·선택 정렬은 평균 O(n²)이고, 병합 정렬은 항상 O(n log n)이지만 추가 메모리가 필요하며, 퀵 정렬은 평균 O(n log n)이나 피벗이 나쁘면 최악 O(n²)입니다. 안정 정렬은 값이 같은 원소의 기존 순서를 유지하는 정렬로, 여러 기준으로 연달아 정렬할 때 중요합니다. Java의 Arrays.sort는 기본형 배열에는 듀얼 피벗 퀵 정렬을, 객체 배열에는 안정 정렬인 병합 계열(TimSort)을 사용합니다.","keywords":["O(n log n)","퀵 정렬 최악","안정 정렬","듀얼 피벗 퀵 정렬","TimSort"],"followups":["기본형 배열과 객체 배열의 정렬 알고리즘이 다른 이유는 무엇이라고 생각하나요?","이미 거의 정렬된 데이터에는 어떤 정렬이 유리한가요?"],"source":"https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/Arrays.html"},{"id":"cs-28","topic":"CS","level":"중","question":"Git의 merge와 rebase의 차이를 설명해 보세요.","answer":"merge는 두 브랜치의 변경을 합치는 새 병합 커밋을 만들어 히스토리를 있는 그대로 보존하고, 한쪽이 다른 쪽의 앞에 있으면 커밋 없이 포인터만 옮기는 fast-forward가 됩니다. rebase는 내 브랜치의 커밋을 대상 브랜치 끝에 다시 적용해 히스토리를 일직선으로 만들지만 커밋이 새로 만들어져 해시가 바뀝니다. 그래서 이미 공유한 브랜치를 rebase하면 다른 사람의 히스토리와 어긋나므로 로컬 정리에만 쓰고, 공유 브랜치는 merge를 씁니다.","keywords":["병합 커밋","fast-forward","커밋 재적용","히스토리 재작성","공유 브랜치 주의"],"followups":["rebase 중 충돌이 나면 어떻게 해결하고 이어가나요?","squash merge는 일반 merge와 어떻게 다른가요?"],"source":"https://git-scm.com/docs/git-rebase"},{"id":"cs-29","topic":"CS","level":"중","question":"Git의 reset과 revert의 차이는 무엇이고 언제 각각 쓰나요?","answer":"reset은 브랜치가 가리키는 커밋을 과거로 옮기는 명령으로, --soft는 커밋만, --mixed는 커밋과 스테이징까지, --hard는 작업 디렉터리까지 되돌려 히스토리를 바꿉니다. revert는 특정 커밋의 변경을 거꾸로 적용하는 새 커밋을 만들어 기존 히스토리를 그대로 두고 취소합니다. 아직 푸시하지 않은 로컬 커밋 정리에는 reset, 이미 공유한 브랜치의 잘못된 커밋 취소에는 안전한 revert를 씁니다.","keywords":["reset --soft/--mixed/--hard","revert","새 커밋","히스토리 보존"],"followups":["git reset --hard 후 날아간 커밋을 복구할 수 있나요?","머지 커밋을 revert하려면 어떤 옵션이 필요한가요?"],"source":"https://git-scm.com/docs/git-revert"},{"id":"cs-30","topic":"CS","level":"중","question":"REST와 RESTful API란 무엇이고, 지켜야 할 제약은 무엇인가요?","answer":"REST는 Roy Fielding이 정리한 웹 아키텍처 스타일로, 클라이언트-서버 분리, 무상태, 캐시 가능, 균일한 인터페이스, 계층형 시스템을 제약으로 둡니다(코드 온 디맨드는 선택). 실무에서는 URI로 리소스를 식별하고 HTTP 메서드로 행위를 표현하며 상태 코드와 표현(JSON)으로 응답하는 설계를 RESTful이라 부릅니다. 예를 들어 GET /users/1, POST /users처럼 명사 URI와 메서드를 조합하고, 서버는 요청마다 필요한 정보를 모두 받아 세션 상태를 저장하지 않습니다.","keywords":["무상태","균일한 인터페이스","리소스 URI","HTTP 메서드","캐시 가능"],"followups":["무상태가 서버 확장에 유리한 이유는 무엇인가요?","Fielding의 정의 기준으로 JSON을 쓰는 대부분의 API가 완전한 REST가 아니라고 하는 이유는 무엇인가요?"],"source":"https://ics.uci.edu/~fielding/pubs/dissertation/rest_arch_style.htm"},{"id":"cs-31","topic":"CS","level":"중","question":"SQL 인젝션이란 무엇이고 어떻게 막나요?","answer":"SQL 인젝션은 사용자 입력이 SQL 문장의 구조로 해석되도록 끼워 넣어 의도하지 않은 쿼리를 실행시키는 공격입니다. 가장 확실한 방어는 입력을 문자열로 이어 붙이지 않고 PreparedStatement 같은 파라미터 바인딩(prepared statements)을 쓰는 것입니다. 컬럼명·정렬 방향처럼 바인딩이 안 되는 부분은 허용 목록(allow-list)으로 검증하고, DB 계정에는 필요한 최소 권한만 줍니다. JPA·MyBatis도 문자열 연결로 쿼리를 만들거나 MyBatis의 ${}를 쓰면 똑같이 위험합니다.","keywords":["prepared statement","파라미터 바인딩","허용 목록","최소 권한"],"followups":["MyBatis의 #{}와 ${}는 어떻게 다른가요?","ORM을 쓰면 SQL 인젝션에서 안전한가요?"],"source":"https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html"},{"id":"cs-32","topic":"CS","level":"중","question":"XSS와 CSRF는 무엇이고 각각 어떻게 방어하나요?","answer":"XSS는 공격자가 심은 스크립트가 피해자 브라우저에서 해당 사이트 권한으로 실행되는 공격으로, 출력 시 컨텍스트에 맞는 이스케이프(output encoding)와 CSP가 핵심 방어입니다. CSRF는 로그인된 사용자의 브라우저가 쿠키를 자동으로 보내는 점을 이용해 사용자가 의도하지 않은 요청을 보내게 하는 공격으로, CSRF 토큰(synchronizer token)이나 double submit, SameSite 쿠키로 막습니다. 즉 XSS는 '내 사이트에 남의 스크립트 실행', CSRF는 '내 인증 상태를 남이 요청에 이용'입니다.","keywords":["output encoding","CSP","CSRF 토큰","SameSite"],"followups":["JWT를 쓰는 stateless API에서 CSRF 방어를 꺼도 되는 경우와 조건은 무엇인가요?","HttpOnly 쿠키는 XSS를 막아 주나요?"],"source":"https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Request_Forgery_Prevention_Cheat_Sheet.html"},{"id":"cs-33","topic":"CS","level":"중","question":"TCP의 흐름 제어와 혼잡 제어는 무엇이 다른가요?","answer":"흐름 제어는 수신자가 처리할 수 있는 양을 넘지 않도록 송신자를 늦추는 것으로, 수신자가 알려 주는 수신 윈도우(receive window)로 조절합니다. 혼잡 제어는 네트워크 중간 경로가 막히지 않도록 송신자가 스스로 보내는 양(혼잡 윈도우, congestion window)을 조절하는 것으로, 슬로 스타트·혼잡 회피·빠른 재전송·빠른 회복이 대표 기법입니다(RFC 5681). 전자는 '받는 쪽 보호', 후자는 '네트워크 보호'입니다.","keywords":["수신 윈도우","혼잡 윈도우","슬로 스타트","빠른 재전송"],"followups":["패킷 손실이 감지되면 혼잡 윈도우는 어떻게 변하나요?","실제 전송량은 두 윈도우 중 무엇에 의해 정해지나요?"],"source":"https://www.rfc-editor.org/rfc/rfc5681"},{"id":"cs-34","topic":"CS","level":"중","question":"인증(Authentication)과 인가(Authorization)의 차이, 그리고 OAuth 2.0은 무엇인가요?","answer":"인증은 '누구인지' 확인하는 것(로그인), 인가는 '무엇을 할 수 있는지' 판단하는 것(권한)입니다. OAuth 2.0은 사용자가 비밀번호를 서드파티 앱에 주지 않고도 자원 서버의 일부 권한을 위임하는 인가 프레임워크입니다. 대표 흐름인 인가 코드(authorization code) 방식은 사용자가 인가 서버에서 동의하면 앱이 코드를 받고, 이를 액세스 토큰(필요시 리프레시 토큰)으로 교환합니다. OAuth 자체는 인가 프로토콜이라 로그인(인증)에는 OpenID Connect를 얹어 씁니다.","keywords":["인증/인가","위임","인가 코드","액세스 토큰","리프레시 토큰"],"followups":["state 파라미터와 redirect_uri 검증은 왜 필요한가요?","소셜 로그인을 붙일 때 내 서버는 토큰을 어떻게 다루나요?"],"source":"https://www.rfc-editor.org/rfc/rfc6749"},{"id":"cs-35","topic":"CS","level":"하","question":"쿠키의 Secure, HttpOnly, 만료 속성은 각각 무엇을 위한 것인가요?","answer":"Secure는 HTTPS 같은 보안 채널로만 쿠키를 보내게 하고, HttpOnly는 JavaScript(document.cookie)로 접근하지 못하게 해 XSS로 인한 쿠키 탈취 위험을 줄입니다(XSS 자체를 막지는 못합니다). Expires/Max-Age는 쿠키의 수명을 정하며(둘 다 있으면 Max-Age가 우선), 없으면 세션 쿠키로 브라우저 종료 시 사라집니다. 참고로 SameSite는 RFC 6265 본문이 아닌 후속 개정판·브라우저가 구현한 속성으로, 다른 사이트에서 시작된 요청에 쿠키를 보낼지 정해 CSRF를 완화합니다.","keywords":["Secure","HttpOnly","Max-Age","SameSite"],"followups":["세션 ID를 쿠키에 담을 때 어떤 속성을 켜야 하나요?","SameSite=Lax와 Strict의 차이는 무엇인가요?"],"source":"https://www.rfc-editor.org/rfc/rfc6265"},{"id":"cs-36","topic":"CS","level":"중","question":"REST API에서 401, 403, 404, 409는 각각 언제 쓰나요?","answer":"401은 인증 정보가 없거나 유효하지 않을 때, 403은 인증은 됐지만 권한이 없을 때입니다. 404는 대상 리소스를 찾지 못했을 때, 409는 리소스의 현재 상태와 충돌할 때(예: 중복 가입, 낙관적 락 충돌)입니다. 생성 성공은 201(Created), 본문 없는 성공은 204(No Content)가 일반적입니다. 상태 코드를 의미에 맞게 쓰면 클라이언트가 에러 처리를 분기하기 쉽습니다.","keywords":["401","403","404","409","201","204"],"followups":["존재하지 않는 리소스와 권한 없는 리소스를 모두 404로 숨기는 경우는 언제인가요?","Spring에서 예외를 이 상태 코드로 매핑하려면 어떻게 하나요?"],"source":"https://www.rfc-editor.org/rfc/rfc9110"},{"id":"cs-37","topic":"CS","level":"중","question":"로드 밸런서는 무엇이고 왜 쓰나요?","answer":"로드 밸런서는 들어오는 트래픽을 여러 서버(대상)에 나눠 보내는 장치입니다. 서버 한 대가 죽어도 헬스 체크로 정상인 서버에만 요청을 보내 가용성과 장애 허용성이 높아지고, 필요에 따라 서버를 추가·제거해도 요청 흐름이 끊기지 않게 할 수 있습니다. TLS 암호화·복호화를 로드 밸런서가 대신 처리하게 할 수도 있습니다. 세션을 서버 메모리에 두면 서버가 바뀔 때 문제가 되므로 세션 공유나 무상태 설계를 함께 고려해야 합니다.","keywords":["트래픽 분산","헬스 체크","가용성","수평 확장","세션"],"followups":["헬스 체크는 어떤 방식으로 하나요?","서버가 여러 대일 때 로그인 세션은 어떻게 유지하나요?"],"source":"https://docs.aws.amazon.com/elasticloadbalancing/latest/userguide/what-is-load-balancing.html"},{"id":"cs-38","topic":"CS","level":"상","question":"Redis로 cache-aside 캐시를 구현하는 방식과 주의점을 설명해 보세요.","answer":"cache-aside는 애플리케이션이 먼저 Redis를 읽고, 없으면(miss) DB에서 읽어 Redis에 저장하는 방식입니다. 데이터를 수정할 때는 DB를 갱신하고 해당 캐시 키를 삭제(무효화)합니다. 키마다 TTL을 두어 오래된 데이터가 제공되는 기간을 제한합니다. 인기 키가 만료되는 순간 많은 요청이 동시에 DB를 조회하는 캐시 스탬피드가 대표적인 위험입니다.","keywords":["cache-aside","miss","TTL","무효화","스탬피드"],"followups":["캐시와 DB 사이 데이터 불일치는 언제 생기나요?","캐시 스탬피드를 어떻게 줄일 수 있나요?"],"source":"https://redis.io/docs/latest/develop/use-cases/cache-aside/"},{"id":"beh-01","topic":"인성","level":"하","question":"1분 자기소개를 해 보세요.","answer":"정답이 없는 질문이라 구조로 준비합니다. 현재 위치(전공·부트캠프 등)와 핵심 기술 한 줄, 그 기술을 쓴 대표 경험 하나(성과나 배운 점 포함), 이 회사·직무에서 하고 싶은 일 한 줄 순서로 말하세요. 이력서를 읽지 말고 면접관이 이어서 물을 만한 키워드를 일부러 남겨 두면 꼬리질문을 내가 유도할 수 있습니다. 60초(약 250자) 안에 끝나게 소리 내어 시간을 재 보세요.","keywords":["현재 위치","핵심 기술","대표 경험 1개","지원 직무 연결"],"followups":["방금 말한 경험 중 가장 자신 있는 것을 더 자세히 설명해 주세요.","그 경험에서 본인이 직접 한 일은 무엇인가요?"],"source":"https://www.amazon.jobs/en/landing_pages/in-person-interview"},{"id":"beh-02","topic":"인성","level":"하","question":"우리 회사(이 직무)에 지원한 이유는 무엇인가요?","answer":"회사 칭찬이 아니라 내 경험과 회사가 하는 일이 만나는 지점을 말합니다. 먼저 회사의 제품·기술 스택·문화 중 직접 조사한 구체적 사실 한두 가지를 들고, 내가 공부하거나 만든 경험이 그것과 어떻게 이어지는지, 입사 후 기여하고 싶은 일을 연결하세요. 어디서나 통하는 답(성장하고 싶어서)만 하지 않도록 이 회사만의 근거를 하나 이상 넣습니다.","keywords":["회사 조사 근거","내 경험과 연결","기여하고 싶은 일"],"followups":["우리 서비스에서 개선하고 싶은 점이 있다면 무엇인가요?","다른 회사에도 지원했다면 이 회사를 선택하는 기준은 무엇인가요?"],"source":"https://www.amazon.jobs/en/landing_pages/in-person-interview"},{"id":"beh-03","topic":"인성","level":"중","question":"가장 자신 있는 프로젝트를 소개하고, 본인의 역할을 설명해 보세요.","answer":"STAR 틀로 말합니다. 상황(어떤 프로젝트·팀·기간), 과제(내가 맡은 목표와 책임), 행동(내가 선택한 기술과 이유, 직접 한 일), 결과(수치나 배운 점)를 2분 안에 정리하세요. 팀 성과와 내 기여를 구분해 말하고, 기술 선택마다 대안과 고른 이유를 준비해 두면 꼬리질문에 흔들리지 않습니다. 숫자가 없으면 개선 전후를 말로라도 비교하세요.","keywords":["STAR","내 역할과 기여","기술 선택 이유","결과·배운 점"],"followups":["그 기술을 선택한 이유와 고려했던 대안은 무엇인가요?","다시 한다면 무엇을 바꾸겠나요?"],"source":"https://www.amazon.jobs/en/landing_pages/in-person-interview"},{"id":"beh-04","topic":"인성","level":"중","question":"기술적으로 가장 어려웠던 문제와 해결 과정을 말해 주세요.","answer":"문제 상황과 왜 어려웠는지를 먼저 짧게 말하고, 원인을 좁혀 간 과정(로그 확인, 재현, 가설 세우기와 검증)을 순서대로 설명하세요. 결론만 말하지 말고 막혔던 지점과 시도했다 실패한 방법도 말하면 깊이 파고드는 태도가 보입니다. 마지막에 같은 문제를 막기 위해 남긴 것(테스트, 문서, 코드 변경)을 덧붙이세요.","keywords":["문제 정의","원인 분석 과정","실패한 시도","재발 방지"],"followups":["처음 세운 가설이 틀렸던 적이 있나요? 어떻게 알았나요?","혼자 해결하기 어려울 때 언제 도움을 요청하나요?"],"source":"https://www.amazon.jobs/content/en/our-workplace/leadership-principles"},{"id":"beh-05","topic":"인성","level":"중","question":"팀원과 의견이 달랐던 경험과 해결 방법을 말해 주세요.","answer":"사람 탓이 아니라 의견 차이의 내용을 중심으로 상황을 설명합니다. 상대 입장을 먼저 듣고 이해한 점, 내 주장의 근거(데이터·사례), 합의에 이른 방법(작은 실험, 기준 정하기, 다수결 후 따르기)을 순서로 말하세요. 내 의견이 채택되지 않았더라도 결정에 동의하고 실행에 협력했다는 점을 보여 주면 좋습니다. 결과 후 관계가 어떻게 되었는지도 한 문장 넣으세요.","keywords":["상대 입장 경청","근거 제시","합의 방법","결정 후 협력"],"followups":["상대가 끝까지 동의하지 않았다면 어떻게 했을까요?","그 경험에서 협업에 대해 배운 점은 무엇인가요?"],"source":"https://www.amazon.jobs/content/en/our-workplace/leadership-principles"},{"id":"beh-06","topic":"인성","level":"중","question":"실패하거나 큰 실수를 했던 경험과 그 이후 달라진 점을 말해 주세요.","answer":"숨기지 말고 실제 실수를 고르되 치명적이지 않은 사례를 선택합니다. 무엇을 잘못했는지 변명 없이 말하고, 영향 범위, 바로 수습한 행동, 근본 원인을 파악해 남긴 개선(체크리스트, 테스트, 프로세스)을 순서로 설명하세요. 개인 책임 추궁이 아니라 원인을 시스템 관점에서 분석하고 배우는 태도가 핵심입니다.","keywords":["솔직한 인정","즉시 수습","근본 원인","재발 방지"],"followups":["같은 실수를 반복하지 않으려고 구체적으로 무엇을 바꿨나요?","다른 사람이 실수했을 때는 어떻게 대하나요?"],"source":"https://sre.google/sre-book/postmortem-culture/"},{"id":"beh-07","topic":"인성","level":"하","question":"새로운 기술을 어떻게 배우나요? 최근에 배운 것을 예로 들어 주세요.","answer":"학습 방법을 구체적 사례와 함께 말합니다. 공식 문서로 개념을 잡고, 작은 예제나 프로젝트에 직접 적용하며, 막힌 부분을 정리해 공유한 과정을 순서로 설명하세요. 최근에 배운 기술 하나와 그걸 쓴 결과물(저장소, 정리 글)을 들면 설득력이 높습니다. 배우는 방법뿐 아니라 어디까지 배우고 멈출지 정하는 기준도 있으면 좋습니다.","keywords":["공식 문서","직접 적용","정리·공유","최근 사례"],"followups":["배운 기술이 업무와 맞지 않았던 적이 있나요?","모르는 기술을 빠르게 익혀야 할 때 우선순위는 어떻게 정하나요?"],"source":"https://www.amazon.jobs/content/en/our-workplace/leadership-principles"},{"id":"beh-08","topic":"인성","level":"중","question":"코드 리뷰에서 내 코드에 대한 지적을 받으면 어떻게 대응하나요?","answer":"리뷰는 코드의 전반적인 품질을 높이기 위한 과정이라 지적을 사람에 대한 평가로 받아들이지 않습니다. 이해가 안 되면 의도를 질문하고, 동의하면 반영한 뒤 알리며, 동의하지 않으면 감정 없이 근거를 설명해 협력적으로 논의합니다. 결론이 안 나면 팀 규칙이나 더 경험 많은 사람의 의견으로 정리하고, 반복되는 지적은 체크리스트로 만들어 다음 PR에서 줄입니다.","keywords":["코드 품질","의도 질문","근거 있는 논의","반복 지적 개선"],"followups":["리뷰어가 취향 차이로 지적한다고 느껴지면 어떻게 하나요?","내가 리뷰어일 때 어떤 점을 중점적으로 보나요?"],"source":"https://google.github.io/eng-practices/review/developer/handling-comments.html"},{"id":"beh-09","topic":"인성","level":"상","question":"일정이 촉박하고 할 일이 많을 때 우선순위를 어떻게 정하고 일을 진행했나요?","answer":"상황을 먼저 말하고, 우선순위 기준(사용자 영향, 마감, 의존 관계, 난이도)으로 일을 나눈 과정을 설명하세요. 범위를 줄이거나 미루는 결정은 혼자 하지 않고 팀과 이해관계자에게 일찍 공유해 기대치를 맞췄다는 점을 보여 주면 좋습니다. 완벽보다 동작하는 최소 결과를 먼저 내고 점검한 사례와, 끝난 뒤 일정 추정을 어떻게 개선했는지로 마무리합니다.","keywords":["우선순위 기준","범위 조정","빠른 공유","최소 결과 먼저"],"followups":["마감을 못 지킬 것 같다는 걸 언제 누구에게 말하나요?","품질과 일정이 충돌하면 어떤 기준으로 선택하나요?"],"source":"https://www.amazon.jobs/content/en/our-workplace/leadership-principles"},{"id":"beh-10","topic":"인성","level":"중","question":"본인의 단점은 무엇이고, 이를 보완하려고 어떤 노력을 하고 있나요?","answer":"업무와 치명적으로 충돌하지 않는 실제 단점을 고르고 구체적 사례로 말합니다. 단점을 인지하게 된 계기, 지금 하고 있는 보완 노력(습관, 도구, 피드백 받기)과 그 결과를 순서로 설명하세요. 장점처럼 포장한 답(너무 완벽주의라서)은 피하고, 아직 진행 중이라는 점도 솔직히 말하는 편이 신뢰를 줍니다.","keywords":["실제 단점","인지 계기","보완 노력","개선 결과"],"followups":["동료가 그 단점을 어떻게 평가할 것 같나요?","단점 보완을 위해 최근 한 달 동안 한 일은 무엇인가요?"],"source":"https://www.amazon.jobs/content/en/our-workplace/leadership-principles"},{"id":"beh-11","topic":"인성","level":"하","question":"마지막으로 저희에게 하고 싶은 질문이 있나요? (역질문)","answer":"정답은 없지만 '없습니다'로 끝내지 않는 것이 좋습니다. 입사 후 처음 맡을 업무와 온보딩, 팀의 코드 리뷰·테스트 문화, 신입이 3개월 안에 기대받는 성과처럼 일에 대한 관심이 드러나는 질문을 2~3개 준비하세요. 공고나 홈페이지에서 답을 찾을 수 있는 질문, 연봉·복지만 묻는 질문은 첫 면접에서는 피하는 편이 낫습니다.","keywords":["준비된 질문 2~3개","온보딩","팀 문화","공고에 없는 내용"],"followups":["방금 질문을 하게 된 이유가 무엇인가요?","우리 팀에서 어떤 기여를 하고 싶으세요?"],"source":""},{"id":"beh-12","topic":"인성","level":"중","question":"프로젝트에서 왜 그 기술(예: JPA, JWT, Redis)을 선택했나요? 대안은 없었나요?","answer":"기술 이름이 아니라 '문제→대안→선택 기준→결과·한계' 순서로 답합니다. 예: 반복 CRUD 비용과 객체-테이블 불일치가 문제라 MyBatis와 비교했고, 도메인 모델 중심 개발과 변경 감지가 이득이라 JPA를 택했지만 N+1 같은 단점은 fetch join으로 대응했다고 말합니다. '유행이라서', '튜토리얼이 그래서'는 피하고, 선택하지 않은 대안과 트레이드오프를 한 가지 이상 말할 수 있어야 합니다. 쓰지 않은 기술은 아는 척하지 마세요.","keywords":["문제 정의","대안 비교","트레이드오프","한계 인정"],"followups":["그 기술을 쓰며 겪은 가장 큰 단점은 무엇이었나요?","지금 다시 선택한다면 바꾸고 싶은 부분이 있나요?"],"source":""}];
